IW_IMPL(int) iw_max_color_to_bitdepth(unsigned int mc)
{
	unsigned int bd;

	for(bd=1;bd<=15;bd++) {
		if(mc < (1U<<bd)) return bd;
	}
	return 16;
}

IW_IMPL(void) iw_set_ui32le(iw_byte *b, unsigned int n)
{
	b[0] = n&0xff;
	b[1] = (n>>8)&0xff;
	b[2] = (n>>16)&0xff;
	b[3] = (n>>24)&0xff;
}

