                                        TabContents* new_contents,
                                        int index,
                                        bool user_gesture) {
  TRACE_EVENT0("ui::gtk", "BrowserWindowGtk::ActiveTabChanged");
  if (old_contents && !old_contents->in_destructor())
    old_contents->web_contents()->GetView()->StoreFocus();

