static bool CombineClip(const ClipPaintPropertyNode* clip,
                        FloatRoundedRect& combined_clip_rect) {
  if (clip->Parent()->ClipPath())
    return false;

  if (clip->LocalTransformSpace() != clip->Parent()->LocalTransformSpace() &&
      !GeometryMapper::SourceToDestinationProjection(
           clip->Parent()->LocalTransformSpace(), clip->LocalTransformSpace())
           .IsIdentity())
    return false;

  bool clip_is_rounded = clip->ClipRect().IsRounded();
  bool combined_is_rounded = combined_clip_rect.IsRounded();
  if (clip_is_rounded && combined_is_rounded)
    return false;

  if (combined_is_rounded)
    return clip->ClipRect().Rect().Contains(combined_clip_rect.Rect());
  if (clip_is_rounded) {
    if (combined_clip_rect.Rect().Contains(clip->ClipRect().Rect())) {
      combined_clip_rect = clip->ClipRect();
      return true;
    }
    return false;
  }

  DCHECK(!combined_is_rounded && !clip_is_rounded);
  combined_clip_rect = FloatRoundedRect(
      Intersection(combined_clip_rect.Rect(), clip->ClipRect().Rect()));
  return true;
}

int PropertyTreeManager::EnsureCompositorClipNode(
    const ClipPaintPropertyNode* clip_node) {
  DCHECK(clip_node);
  if (!clip_node)
    return kSecondaryRootNodeId;

  auto it = clip_node_map_.find(clip_node);
  if (it != clip_node_map_.end())
    return it->value;

  int parent_id = EnsureCompositorClipNode(clip_node->Parent());
  int id = GetClipTree().Insert(cc::ClipNode(), parent_id);

  cc::ClipNode& compositor_node = *GetClipTree().Node(id);

  compositor_node.clip = clip_node->ClipRect().Rect();
  compositor_node.transform_id =
      EnsureCompositorTransformNode(clip_node->LocalTransformSpace());
  compositor_node.clip_type = cc::ClipNode::ClipType::APPLIES_LOCAL_CLIP;

  auto result = clip_node_map_.Set(clip_node, id);
  DCHECK(result.is_new_entry);
  GetClipTree().set_needs_update(true);
  return id;
}

