      GetLastCommittedEntry()->CloneAndReplace(
          frame_entry.get(), is_in_page, rfh->frame_tree_node(),
          delegate_->GetFrameTree()->root());


  InsertOrReplaceEntry(std::move(new_entry), replace_entry);
}

