static bool CheckMJpeg(const uint8_t* buffer, int buffer_size) {
  RCHECK(buffer_size >= 16);

  int offset = 0;
  int last_restart = -1;
  int num_codes = 0;
  while (offset + 5 < buffer_size) {
    RCHECK(buffer[offset] == 0xff);
    uint8_t code = buffer[offset + 1];
    RCHECK(code >= 0xc0 || code == 1);

    if (code == 0xff) {
      ++offset;
      continue;
    }

    if (code == 0xd9)
      return true;

    if (code == 0xd8 || code == 1) {
      offset += 2;
    } else if (code >= 0xd0 && code <= 0xd7) {
      int restart = code & 0x07;
      if (last_restart >= 0)
        RCHECK(restart == (last_restart + 1) % 8);
      last_restart = restart;
      offset += 2;
    } else {
      int length = Read16(buffer + offset + 2) + 2;

      if (code == 0xda) {
        int number_components = buffer[offset + 4];
        RCHECK(length == 8 + 2 * number_components);

        offset += length;
        while (offset + 2 < buffer_size) {
          if (buffer[offset] == 0xff && buffer[offset + 1] != 0)
            break;
          ++offset;
        }
      } else {
        offset += length;
      }
    }
    ++num_codes;
  }
  return (num_codes > 1);
}

static uint64_t GetVint(BitReader* reader) {
  if (reader->bits_available() >= 8) {
    int num_bits_to_read = 0;
    for (int i = 0; i < 8; ++i) {
      num_bits_to_read += 7;
      if (ReadBits(reader, 1) == 1) {
        if (reader->bits_available() < num_bits_to_read)
          break;
        return ReadBits(reader, num_bits_to_read);
      }
    }
  }
  return (reader->bits_available() / 8) + 2;
}

bool CheckDownloadFullPaths(Browser* browser,
                            const base::FilePath& downloaded_file,
                            const base::FilePath& origin_file) {
  base::ScopedAllowBlockingForTesting allow_blocking;
  bool origin_file_exists = base::PathExists(origin_file);
  EXPECT_TRUE(origin_file_exists) << origin_file.value();
  if (!origin_file_exists)
    return false;

  bool downloaded_file_exists = base::PathExists(downloaded_file);
  EXPECT_TRUE(downloaded_file_exists) << downloaded_file.value();
  if (!downloaded_file_exists)
    return false;

  int64_t origin_file_size = 0;
  EXPECT_TRUE(base::GetFileSize(origin_file, &origin_file_size));
  std::string original_file_contents;
  EXPECT_TRUE(base::ReadFileToString(origin_file, &original_file_contents));
  EXPECT_TRUE(
      VerifyFile(downloaded_file, original_file_contents, origin_file_size));

  bool downloaded_file_deleted = base::DieFileDie(downloaded_file, false);
  EXPECT_TRUE(downloaded_file_deleted);
  return downloaded_file_deleted;
}

