static void hex_dump(char *msg, void *data, int size, int trunc)
{
 unsigned char *p = data;
 unsigned char c;
 int n;
 char bytestr[4] = {0};
 char addrstr[10] = {0};
 char hexstr[ 16*3 + 5] = {0};
 char charstr[16*1 + 5] = {0};

    bdt_log("%s  \n", msg);

 /* truncate */
 if(trunc && (size>32))
        size = 32;

 for(n=1;n<=size;n++) {
 if (n%16 == 1) {
 /* store address for this line */
            snprintf(addrstr, sizeof(addrstr), "%.4x",
 (unsigned int)((uintptr_t)p-(uintptr_t)data) );
 }

        c = *p;
 if (isalnum(c) == 0) {
            c = '.';
 }

 /* store hex str (for left side) */
        snprintf(bytestr, sizeof(bytestr), "%02X ", *p);
        strncat(hexstr, bytestr, sizeof(hexstr)-strlen(hexstr)-1);

 /* store char str (for right side) */
        snprintf(bytestr, sizeof(bytestr), "%c", c);
        strncat(charstr, bytestr, sizeof(charstr)-strlen(charstr)-1);

 if(n%16 == 0) {
 /* line completed */
            bdt_log("[%4.4s]   %-50.50s  %s\n", addrstr, hexstr, charstr);
            hexstr[0] = 0;
            charstr[0] = 0;
 } else if(n%8 == 0) {
 /* half line: add whitespaces */
            strncat(hexstr, "  ", sizeof(hexstr)-strlen(hexstr)-1);
            strncat(charstr, " ", sizeof(charstr)-strlen(charstr)-1);
 }
        p++; /* next byte */
 }

 if (strlen(hexstr) > 0) {
 /* print rest of buffer if not empty */
        bdt_log("[%4.4s]   %-50.50s  %s\n", addrstr, hexstr, charstr);
 }
}

static void print_fds(struct pid_info_t* info)
{
 static char* fd_path = "fd/";
    strlcat(info->path, fd_path, sizeof(info->path));

 int previous_length = info->parent_length;
    info->parent_length += strlen(fd_path);

 DIR *dir = opendir(info->path);
 if (dir == NULL) {
 char msg[BUF_MAX];
        snprintf(msg, sizeof(msg), "%s (opendir: %s)", info->path, strerror(errno));
        printf("%-9s %5d %10s %4s %9s %18s %9s %10s %s\n",
                info->cmdline, info->pid, info->user, "FDS",
 "", "", "", "", msg);
 goto out;
 }

 struct dirent* de;
 while ((de = readdir(dir))) {
 if (!strcmp(de->d_name, ".") || !strcmp(de->d_name, ".."))
 continue;

        print_type(de->d_name, info);
 }
    closedir(dir);

out:
    info->parent_length = previous_length;
    info->path[info->parent_length] = '\0';
}

 component(png_const_bytep row, png_uint_32 x, unsigned int c,
 unsigned int bit_depth, unsigned int channels)
{
 /* PNG images can be up to 2^31 pixels wide, but this means they can be up to
    * 2^37 bits wide (for a 64-bit pixel - the largest possible) and hence 2^34
    * bytes wide.  Since the row fitted into memory, however, the following must
    * work:
    */
   png_uint_32 bit_offset_hi = bit_depth * ((x >> 6) * channels);
   png_uint_32 bit_offset_lo = bit_depth * ((x & 0x3f) * channels + c);

   row = (png_const_bytep)(((PNG_CONST png_byte (*)[8])row) + bit_offset_hi);
   row += bit_offset_lo >> 3;
   bit_offset_lo &= 0x07;

 /* PNG pixels are packed into bytes to put the first pixel in the highest
    * bits of the byte and into two bytes for 16-bit values with the high 8 bits
    * first, so:
    */
 switch (bit_depth)
 {
 case 1: return (row[0] >> (7-bit_offset_lo)) & 0x01;
 case 2: return (row[0] >> (6-bit_offset_lo)) & 0x03;
 case 4: return (row[0] >> (4-bit_offset_lo)) & 0x0f;
 case 8: return row[0];
 case 16: return (row[0] << 8) + row[1];
 default:
 /* This should never happen; it indicates a bug in this program or in
          * libpng itself:
          */
         fprintf(stderr, "pngpixel: invalid bit depth %u\n", bit_depth);
         exit(1);
 }
}

int main(int argc, const char **argv)
{
int result = 1;

if (argc == 3)
{
     png_image image;

/* Only the image structure version number needs to be set. */
     memset(&image, 0, sizeof image);
     image.version = PNG_IMAGE_VERSION;

if (png_image_begin_read_from_file(&image, argv[1]))
{
        png_bytep buffer;

/* Change this to try different formats!  If you set a colormap format
         * then you must also supply a colormap below.
         */
        image.format = PNG_FORMAT_RGBA;

        buffer = malloc(PNG_IMAGE_SIZE(image));

if (buffer != NULL)
{
if (png_image_finish_read(&image, NULL/*background*/, buffer,
0/*row_stride*/, NULL/*colormap for PNG_FORMAT_FLAG_COLORMAP */))
{
if (png_image_write_to_file(&image, argv[2],
0/*convert_to_8bit*/, buffer, 0/*row_stride*/,
                 NULL/*colormap*/))
                 result = 0;

else
                 fprintf(stderr, "pngtopng: write %s: %s\n", argv[2],
                     image.message);

              free(buffer);
}

else
{
              fprintf(stderr, "pngtopng: read %s: %s\n", argv[1],
                  image.message);

/* This is the only place where a 'free' is required; libpng does
               * the cleanup on error and success, but in this case we couldn't
               * complete the read because of running out of memory.
               */
              png_image_free(&image);
}
}

else
           fprintf(stderr, "pngtopng: out of memory: %lu bytes\n",
(unsigned long)PNG_IMAGE_SIZE(image));
}

else
/* Failed to read the first argument: */
        fprintf(stderr, "pngtopng: %s: %s\n", argv[1], image.message);
}

else
/* Wrong number of arguments */
     fprintf(stderr, "pngtopng: usage: pngtopng input-file output-file\n");


   return result;
}

