OMX_ERRORTYPE  omx_vdec::use_EGL_image(OMX_IN OMX_HANDLETYPE     hComp,
        OMX_INOUT OMX_BUFFERHEADERTYPE** bufferHdr,
        OMX_IN OMX_U32                        port,
        OMX_IN OMX_PTR                     appData,
        OMX_IN void*                      eglImage)
{
 (void) appData;
    OMX_QCOM_PLATFORM_PRIVATE_LIST pmem_list;
    OMX_QCOM_PLATFORM_PRIVATE_ENTRY pmem_entry;
    OMX_QCOM_PLATFORM_PRIVATE_PMEM_INFO pmem_info;

#ifdef USE_EGL_IMAGE_GPU
    PFNEGLQUERYIMAGEQUALCOMMPROC egl_queryfunc;
 EGLint fd = -1, offset = 0,pmemPtr = 0;
#else
 int fd = -1, offset = 0;
#endif
    DEBUG_PRINT_HIGH("use EGL image support for decoder");
 if (!bufferHdr || !eglImage|| port != OMX_CORE_OUTPUT_PORT_INDEX) {
        DEBUG_PRINT_ERROR("Invalid EGL image");
 }
#ifdef USE_EGL_IMAGE_GPU
 if (m_display_id == NULL) {
        DEBUG_PRINT_ERROR("Display ID is not set by IL client");
 return OMX_ErrorInsufficientResources;
 }
    egl_queryfunc = (PFNEGLQUERYIMAGEQUALCOMMPROC)
        eglGetProcAddress("eglQueryImageKHR");
    egl_queryfunc(m_display_id, eglImage, EGL_BUFFER_HANDLE, &fd);
    egl_queryfunc(m_display_id, eglImage, EGL_BUFFER_OFFSET, &offset);
    egl_queryfunc(m_display_id, eglImage, EGL_BITMAP_POINTER_KHR,&pmemPtr);
#else //with OMX test app
 struct temp_egl {
 int pmem_fd;
 int offset;
 };
 struct temp_egl *temp_egl_id = NULL;
 void * pmemPtr = (void *) eglImage;
    temp_egl_id = (struct temp_egl *)eglImage;
 if (temp_egl_id != NULL) {
        fd = temp_egl_id->pmem_fd;
        offset = temp_egl_id->offset;
 }
#endif
 if (fd < 0) {
        DEBUG_PRINT_ERROR("Improper pmem fd by EGL client %d",fd);
 return OMX_ErrorInsufficientResources;
 }
    pmem_info.pmem_fd = (OMX_U32) fd;
    pmem_info.offset = (OMX_U32) offset;
    pmem_entry.entry = (void *) &pmem_info;
    pmem_entry.type = OMX_QCOM_PLATFORM_PRIVATE_PMEM;
    pmem_list.entryList = &pmem_entry;
    pmem_list.nEntries = 1;
    ouput_egl_buffers = true;
 if (OMX_ErrorNone != use_buffer(hComp,bufferHdr, port,
 (void *)&pmem_list, drv_ctx.op_buf.buffer_size,
 (OMX_U8 *)pmemPtr)) {
        DEBUG_PRINT_ERROR("use buffer call failed for egl image");
 return OMX_ErrorInsufficientResources;
 }
 return OMX_ErrorNone;
}

static int effect_set_state(struct effect_s *effect, uint32_t state)
{
 int status = 0;
    ALOGV("effect_set_state() id %d, new %d old %d", effect->id, state, effect->state);
 switch(state) {
 case EFFECT_STATE_INIT:
 switch(effect->state) {
 case EFFECT_STATE_ACTIVE:
            session_set_fx_enabled(effect->session, effect->id, false);
 case EFFECT_STATE_CONFIG:
 case EFFECT_STATE_CREATED:
 case EFFECT_STATE_INIT:
 break;
 default:
            BAD_STATE_ABORT(effect->state, state);
 }
 break;
 case EFFECT_STATE_CREATED:
 switch(effect->state) {
 case EFFECT_STATE_INIT:
 break;
 case EFFECT_STATE_CREATED:
 case EFFECT_STATE_ACTIVE:
 case EFFECT_STATE_CONFIG:
            ALOGE("effect_set_state() invalid transition");
            status = -ENOSYS;
 break;
 default:
            BAD_STATE_ABORT(effect->state, state);
 }
 break;
 case EFFECT_STATE_CONFIG:
 switch(effect->state) {
 case EFFECT_STATE_INIT:
            ALOGE("effect_set_state() invalid transition");
            status = -ENOSYS;
 break;
 case EFFECT_STATE_ACTIVE:
            session_set_fx_enabled(effect->session, effect->id, false);
 break;
 case EFFECT_STATE_CREATED:
 case EFFECT_STATE_CONFIG:
 break;
 default:
            BAD_STATE_ABORT(effect->state, state);
 }
 break;
 case EFFECT_STATE_ACTIVE:
 switch(effect->state) {
 case EFFECT_STATE_INIT:
 case EFFECT_STATE_CREATED:
            ALOGE("effect_set_state() invalid transition");
            status = -ENOSYS;
 break;
 case EFFECT_STATE_ACTIVE:
 break;
 case EFFECT_STATE_CONFIG:
            session_set_fx_enabled(effect->session, effect->id, true);
 break;
 default:
            BAD_STATE_ABORT(effect->state, state);
 }
 break;
 default:
        BAD_STATE_ABORT(effect->state, state);
 }

 if (status == 0)
        effect->state = state;

 return status;
}

static int session_create_effect(struct session_s *session,
 int32_t id,
 effect_handle_t *interface)
{
 int status = -ENOMEM;

    ALOGV("session_create_effect() %s, created_msk %08x",
          id == AEC_ID ? "AEC" : id == NS_ID ? "NS" : "?", session->created_msk);

 if (session->created_msk == 0) {
        session->config.inputCfg.samplingRate = 16000;
        session->config.inputCfg.channels = AUDIO_CHANNEL_IN_MONO;
        session->config.inputCfg.format = AUDIO_FORMAT_PCM_16_BIT;
        session->config.outputCfg.samplingRate = 16000;
        session->config.outputCfg.channels = AUDIO_CHANNEL_IN_MONO;
        session->config.outputCfg.format = AUDIO_FORMAT_PCM_16_BIT;
        session->enabled_msk = 0;
        session->processed_msk = 0;
 }
    status = effect_create(&session->effects[id], session, interface);
 if (status < 0)
 goto error;

    ALOGV("session_create_effect() OK");
    session->created_msk |= (1<<id);
 return status;

error:
 return status;
}

static int session_release_effect(struct session_s *session,
 struct effect_s *fx)
{
    ALOGW_IF(effect_release(fx) != 0, " session_release_effect() failed for id %d", fx->id);

    session->created_msk &= ~(1<<fx->id);
 if (session->created_msk == 0)
 {
        ALOGV("session_release_effect() last effect: removing session");
        list_remove(&session->node);
        free(session);
 }

 return 0;
}

status_t NuPlayer::GenericSource::doSelectTrack(size_t trackIndex, bool select, int64_t timeUs) {
 if (trackIndex >= mSources.size()) {
 return BAD_INDEX;
 }

 if (!select) {
 Track* track = NULL;
 if (mSubtitleTrack.mSource != NULL && trackIndex == mSubtitleTrack.mIndex) {
            track = &mSubtitleTrack;
            mFetchSubtitleDataGeneration++;
 } else if (mTimedTextTrack.mSource != NULL && trackIndex == mTimedTextTrack.mIndex) {
            track = &mTimedTextTrack;
            mFetchTimedTextDataGeneration++;
 }
 if (track == NULL) {
 return INVALID_OPERATION;
 }
        track->mSource->stop();
        track->mSource = NULL;
        track->mPackets->clear();
 return OK;
 }

 const sp<MediaSource> source = mSources.itemAt(trackIndex);
    sp<MetaData> meta = source->getFormat();
 const char *mime;
    CHECK(meta->findCString(kKeyMIMEType, &mime));
 if (!strncasecmp(mime, "text/", 5)) {
 bool isSubtitle = strcasecmp(mime, MEDIA_MIMETYPE_TEXT_3GPP);
 Track *track = isSubtitle ? &mSubtitleTrack : &mTimedTextTrack;
 if (track->mSource != NULL && track->mIndex == trackIndex) {
 return OK;
 }
        track->mIndex = trackIndex;
 if (track->mSource != NULL) {
            track->mSource->stop();
 }
        track->mSource = mSources.itemAt(trackIndex);
        track->mSource->start();
 if (track->mPackets == NULL) {
            track->mPackets = new AnotherPacketSource(track->mSource->getFormat());
 } else {
            track->mPackets->clear();
            track->mPackets->setFormat(track->mSource->getFormat());

 }

 if (isSubtitle) {
            mFetchSubtitleDataGeneration++;
 } else {
            mFetchTimedTextDataGeneration++;
 }

 status_t eosResult; // ignored
 if (mSubtitleTrack.mSource != NULL
 && !mSubtitleTrack.mPackets->hasBufferAvailable(&eosResult)) {
            sp<AMessage> msg = new AMessage(kWhatFetchSubtitleData, this);
            msg->setInt64("timeUs", timeUs);
            msg->setInt32("generation", mFetchSubtitleDataGeneration);
            msg->post();
 }

 if (mTimedTextTrack.mSource != NULL
 && !mTimedTextTrack.mPackets->hasBufferAvailable(&eosResult)) {
            sp<AMessage> msg = new AMessage(kWhatFetchTimedTextData, this);
            msg->setInt64("timeUs", timeUs);
            msg->setInt32("generation", mFetchTimedTextDataGeneration);
            msg->post();
 }

 return OK;
 } else if (!strncasecmp(mime, "audio/", 6) || !strncasecmp(mime, "video/", 6)) {
 bool audio = !strncasecmp(mime, "audio/", 6);
 Track *track = audio ? &mAudioTrack : &mVideoTrack;
 if (track->mSource != NULL && track->mIndex == trackIndex) {
 return OK;
 }

        sp<AMessage> msg = new AMessage(kWhatChangeAVSource, this);
        msg->setInt32("trackIndex", trackIndex);
        msg->post();
 return OK;
 }

 return INVALID_OPERATION;
}

void NuPlayer::GenericSource::onSelectTrack(sp<AMessage> msg) {
 int32_t trackIndex, select;
 int64_t timeUs;
    CHECK(msg->findInt32("trackIndex", &trackIndex));
    CHECK(msg->findInt32("select", &select));
    CHECK(msg->findInt64("timeUs", &timeUs));

    sp<AMessage> response = new AMessage;
 status_t err = doSelectTrack(trackIndex, select, timeUs);
    response->setInt32("err", err);

    sp<AReplyToken> replyID;
    CHECK(msg->senderAwaitsResponse(&replyID));
    response->postReply(replyID);
}

void NuPlayer::GenericSource::resetDataSource() {
    mHTTPService.clear();
    mHttpSource.clear();
    mUri.clear();
    mUriHeaders.clear();
 if (mFd >= 0) {
        close(mFd);
        mFd = -1;
 }
    mOffset = 0;
    mLength = 0;
    setDrmPlaybackStatusIfNeeded(Playback::STOP, 0);
    mDecryptHandle = NULL;
    mDrmManagerClient = NULL;
    mStarted = false;
    mStopRead = true;
}

void NuPlayer::GenericSource::sendCacheStats() {
 int32_t kbps = 0;
 status_t err = UNKNOWN_ERROR;

 if (mWVMExtractor != NULL) {
        err = mWVMExtractor->getEstimatedBandwidthKbps(&kbps);
 } else if (mCachedSource != NULL) {
        err = mCachedSource->getEstimatedBandwidthKbps(&kbps);
 }

 if (err == OK) {
        sp<AMessage> notify = dupNotify();
        notify->setInt32("what", kWhatCacheStats);
        notify->setInt32("bandwidth", kbps);
        notify->post();
 }
}

status_t NuPlayer::GenericSource::setDataSource(
 const sp<IMediaHTTPService> &httpService,
 const char *url,
 const KeyedVector<String8, String8> *headers) {
    resetDataSource();

    mHTTPService = httpService;
    mUri = url;

 if (headers) {
        mUriHeaders = *headers;
 }

 return OK;
}

status_t SampleIterator::findChunkRange(uint32_t sampleIndex) {
    CHECK(sampleIndex >= mFirstChunkSampleIndex);

 while (sampleIndex >= mStopChunkSampleIndex) {
 if (mSampleToChunkIndex == mTable->mNumSampleToChunkOffsets) {
 return ERROR_OUT_OF_RANGE;
 }

        mFirstChunkSampleIndex = mStopChunkSampleIndex;

 const SampleTable::SampleToChunkEntry *entry =
 &mTable->mSampleToChunkEntries[mSampleToChunkIndex];

        mFirstChunk = entry->startChunk;
        mSamplesPerChunk = entry->samplesPerChunk;
        mChunkDesc = entry->chunkDesc;

 if (mSampleToChunkIndex + 1 < mTable->mNumSampleToChunkOffsets) {
            mStopChunk = entry[1].startChunk;

            mStopChunkSampleIndex =
                mFirstChunkSampleIndex
 + (mStopChunk - mFirstChunk) * mSamplesPerChunk;
 } else {
            mStopChunk = 0xffffffff;
            mStopChunkSampleIndex = 0xffffffff;
 }

 ++mSampleToChunkIndex;
 }

 return OK;
}

u32 h264bsdCheckAccessUnitBoundary(
 strmData_t *strm,
 nalUnit_t *nuNext,
 storage_t *storage,
  u32 *accessUnitBoundaryFlag)
{

/* Variables */

    u32 tmp, ppsId, frameNum, idrPicId, picOrderCntLsb;
    i32 deltaPicOrderCntBottom, deltaPicOrderCnt[2];
 seqParamSet_t *sps;
 picParamSet_t *pps;

/* Code */

    ASSERT(strm);
    ASSERT(nuNext);
    ASSERT(storage);
    ASSERT(storage->sps);
    ASSERT(storage->pps);

 /* initialize default output to FALSE */
 *accessUnitBoundaryFlag = HANTRO_FALSE;

 if ( ( (nuNext->nalUnitType > 5) && (nuNext->nalUnitType < 12) ) ||
 ( (nuNext->nalUnitType > 12) && (nuNext->nalUnitType <= 18) ) )
 {
 *accessUnitBoundaryFlag = HANTRO_TRUE;
 return(HANTRO_OK);
 }
 else if ( nuNext->nalUnitType != NAL_CODED_SLICE &&
              nuNext->nalUnitType != NAL_CODED_SLICE_IDR )
 {
 return(HANTRO_OK);
 }

 /* check if this is the very first call to this function */
 if (storage->aub->firstCallFlag)
 {
 *accessUnitBoundaryFlag = HANTRO_TRUE;
        storage->aub->firstCallFlag = HANTRO_FALSE;
 }

 /* get picture parameter set id */
    tmp = h264bsdCheckPpsId(strm, &ppsId);
 if (tmp != HANTRO_OK)
 return(tmp);

 /* store sps and pps in separate pointers just to make names shorter */
    pps = storage->pps[ppsId];
 if ( pps == NULL || storage->sps[pps->seqParameterSetId] == NULL  ||
 (storage->activeSpsId != MAX_NUM_SEQ_PARAM_SETS &&
          pps->seqParameterSetId != storage->activeSpsId &&
          nuNext->nalUnitType != NAL_CODED_SLICE_IDR) )
 return(PARAM_SET_ERROR);
    sps = storage->sps[pps->seqParameterSetId];

 if (storage->aub->nuPrev->nalRefIdc != nuNext->nalRefIdc &&
 (storage->aub->nuPrev->nalRefIdc == 0 || nuNext->nalRefIdc == 0))
 *accessUnitBoundaryFlag = HANTRO_TRUE;

 if ((storage->aub->nuPrev->nalUnitType == NAL_CODED_SLICE_IDR &&
          nuNext->nalUnitType != NAL_CODED_SLICE_IDR) ||
 (storage->aub->nuPrev->nalUnitType != NAL_CODED_SLICE_IDR &&
       nuNext->nalUnitType == NAL_CODED_SLICE_IDR))
 *accessUnitBoundaryFlag = HANTRO_TRUE;

    tmp = h264bsdCheckFrameNum(strm, sps->maxFrameNum, &frameNum);
 if (tmp != HANTRO_OK)
 return(HANTRO_NOK);

 if (storage->aub->prevFrameNum != frameNum)
 {
        storage->aub->prevFrameNum = frameNum;
 *accessUnitBoundaryFlag = HANTRO_TRUE;
 }

 if (nuNext->nalUnitType == NAL_CODED_SLICE_IDR)
 {
        tmp = h264bsdCheckIdrPicId(strm, sps->maxFrameNum, nuNext->nalUnitType,
 &idrPicId);
 if (tmp != HANTRO_OK)
 return(HANTRO_NOK);

 if (storage->aub->nuPrev->nalUnitType == NAL_CODED_SLICE_IDR &&
          storage->aub->prevIdrPicId != idrPicId)
 *accessUnitBoundaryFlag = HANTRO_TRUE;

        storage->aub->prevIdrPicId = idrPicId;
 }

 if (sps->picOrderCntType == 0)
 {
        tmp = h264bsdCheckPicOrderCntLsb(strm, sps, nuNext->nalUnitType,
 &picOrderCntLsb);
 if (tmp != HANTRO_OK)
 return(HANTRO_NOK);

 if (storage->aub->prevPicOrderCntLsb != picOrderCntLsb)
 {
            storage->aub->prevPicOrderCntLsb = picOrderCntLsb;
 *accessUnitBoundaryFlag = HANTRO_TRUE;
 }

 if (pps->picOrderPresentFlag)
 {
            tmp = h264bsdCheckDeltaPicOrderCntBottom(strm, sps,
                nuNext->nalUnitType, &deltaPicOrderCntBottom);
 if (tmp != HANTRO_OK)
 return(tmp);

 if (storage->aub->prevDeltaPicOrderCntBottom !=
                deltaPicOrderCntBottom)
 {
                storage->aub->prevDeltaPicOrderCntBottom =
                    deltaPicOrderCntBottom;
 *accessUnitBoundaryFlag = HANTRO_TRUE;
 }
 }
 }
 else if (sps->picOrderCntType == 1 && !sps->deltaPicOrderAlwaysZeroFlag)
 {
        tmp = h264bsdCheckDeltaPicOrderCnt(strm, sps, nuNext->nalUnitType,
          pps->picOrderPresentFlag, deltaPicOrderCnt);
 if (tmp != HANTRO_OK)
 return(tmp);

 if (storage->aub->prevDeltaPicOrderCnt[0] != deltaPicOrderCnt[0])
 {
            storage->aub->prevDeltaPicOrderCnt[0] = deltaPicOrderCnt[0];
 *accessUnitBoundaryFlag = HANTRO_TRUE;
 }

 if (pps->picOrderPresentFlag)
 if (storage->aub->prevDeltaPicOrderCnt[1] != deltaPicOrderCnt[1])
 {
                storage->aub->prevDeltaPicOrderCnt[1] = deltaPicOrderCnt[1];
 *accessUnitBoundaryFlag = HANTRO_TRUE;
 }
 }

 *storage->aub->nuPrev = *nuNext;

 return(HANTRO_OK);

}

u32 h264bsdValidParamSets(storage_t *pStorage)
{

/* Variables */

    u32 i;

/* Code */

    ASSERT(pStorage);

 for (i = 0; i < MAX_NUM_PIC_PARAM_SETS; i++)
 {
 if ( pStorage->pps[i] &&
             pStorage->sps[pStorage->pps[i]->seqParameterSetId] &&
 CheckPps(pStorage->pps[i],
                      pStorage->sps[pStorage->pps[i]->seqParameterSetId]) ==
                 HANTRO_OK)
 {
 return(HANTRO_OK);
 }
 }

 return(HANTRO_NOK);

}

status_t ATSParser::parsePID(
 ABitReader *br, unsigned PID,
 unsigned continuity_counter,
 unsigned payload_unit_start_indicator,
 SyncEvent *event) {
 ssize_t sectionIndex = mPSISections.indexOfKey(PID);

 if (sectionIndex >= 0) {
        sp<PSISection> section = mPSISections.valueAt(sectionIndex);

 if (payload_unit_start_indicator) {
 if (!section->isEmpty()) {
                ALOGW("parsePID encounters payload_unit_start_indicator when section is not empty");
                section->clear();
 }

 unsigned skip = br->getBits(8);
            section->setSkipBytes(skip + 1); // skip filler bytes + pointer field itself
            br->skipBits(skip * 8);
 }

 if (br->numBitsLeft() % 8 != 0) {
 return ERROR_MALFORMED;
 }
 status_t err = section->append(br->data(), br->numBitsLeft() / 8);

 if (err != OK) {
 return err;
 }

 if (!section->isComplete()) {
 return OK;
 }

 if (!section->isCRCOkay()) {
 return BAD_VALUE;
 }
 ABitReader sectionBits(section->data(), section->size());

 if (PID == 0) {
            parseProgramAssociationTable(&sectionBits);
 } else {
 bool handled = false;
 for (size_t i = 0; i < mPrograms.size(); ++i) {
 status_t err;
 if (!mPrograms.editItemAt(i)->parsePSISection(
                            PID, &sectionBits, &err)) {
 continue;
 }

 if (err != OK) {
 return err;
 }

                handled = true;
 break;
 }

 if (!handled) {
                mPSISections.removeItem(PID);
                section.clear();
 }
 }

 if (section != NULL) {
            section->clear();
 }

 return OK;
 }

 bool handled = false;
 for (size_t i = 0; i < mPrograms.size(); ++i) {
 status_t err;
 if (mPrograms.editItemAt(i)->parsePID(
                    PID, continuity_counter, payload_unit_start_indicator,
                    br, &err, event)) {
 if (err != OK) {
 return err;
 }

            handled = true;
 break;
 }
 }

 if (!handled) {
        ALOGV("PID 0x%04x not handled.", PID);
 }

 return OK;
}

