static char* find_file_within(const char* path, const char* name,
 char* buf, size_t bufsize, int search)
{
 size_t pathlen = strlen(path);
 size_t namelen = strlen(name);
 size_t childlen = pathlen + namelen + 1;
 char* actual;

 if (bufsize <= childlen) {
 return NULL;
 }

    memcpy(buf, path, pathlen);
    buf[pathlen] = '/';
    actual = buf + pathlen + 1;
    memcpy(actual, name, namelen + 1);

 if (search && access(buf, F_OK)) {
 struct dirent* entry;
 DIR* dir = opendir(path);
 if (!dir) {
            ERROR("opendir %s failed: %s\n", path, strerror(errno));
 return actual;
 }
 while ((entry = readdir(dir))) {
 if (!strcasecmp(entry->d_name, name)) {
 /* we have a match - replace the name, don't need to copy the null again */
                memcpy(actual, entry->d_name, namelen);
 break;
 }
 }
        closedir(dir);
 }
 return actual;
}

static int fuse_reply_attr(struct fuse* fuse, __u64 unique, const struct node* node,
 const char* path)
{
 struct fuse_attr_out out;
 struct stat s;

 if (lstat(path, &s) < 0) {
 return -errno;
 }
    memset(&out, 0, sizeof(out));
    attr_from_stat(fuse, &out.attr, &s, node);
    out.attr_valid = 10;
    fuse_reply(fuse, unique, &out, sizeof(out));
 return NO_STATUS;
}

static void fuse_status(struct fuse *fuse, __u64 unique, int err)
{
 struct fuse_out_header hdr;
    hdr.len = sizeof(hdr);
    hdr.error = err;
    hdr.unique = unique;
    write(fuse->fd, &hdr, sizeof(hdr));
}

static int handle_fuse_request(struct fuse *fuse, struct fuse_handler* handler,
 const struct fuse_in_header *hdr, const void *data, size_t data_len)
{
 switch (hdr->opcode) {
 case FUSE_LOOKUP: { /* bytez[] -> entry_out */
 const char* name = data;
 return handle_lookup(fuse, handler, hdr, name);
 }

 case FUSE_FORGET: {
 const struct fuse_forget_in *req = data;
 return handle_forget(fuse, handler, hdr, req);
 }

 case FUSE_GETATTR: { /* getattr_in -> attr_out */
 const struct fuse_getattr_in *req = data;
 return handle_getattr(fuse, handler, hdr, req);
 }

 case FUSE_SETATTR: { /* setattr_in -> attr_out */
 const struct fuse_setattr_in *req = data;
 return handle_setattr(fuse, handler, hdr, req);
 }

 case FUSE_MKNOD: { /* mknod_in, bytez[] -> entry_out */
 const struct fuse_mknod_in *req = data;
 const char *name = ((const char*) data) + sizeof(*req);
 return handle_mknod(fuse, handler, hdr, req, name);
 }

 case FUSE_MKDIR: { /* mkdir_in, bytez[] -> entry_out */
 const struct fuse_mkdir_in *req = data;
 const char *name = ((const char*) data) + sizeof(*req);
 return handle_mkdir(fuse, handler, hdr, req, name);
 }

 case FUSE_UNLINK: { /* bytez[] -> */
 const char* name = data;
 return handle_unlink(fuse, handler, hdr, name);
 }

 case FUSE_RMDIR: { /* bytez[] -> */
 const char* name = data;
 return handle_rmdir(fuse, handler, hdr, name);
 }

 case FUSE_RENAME: { /* rename_in, oldname, newname ->  */
 const struct fuse_rename_in *req = data;
 const char *old_name = ((const char*) data) + sizeof(*req);
 const char *new_name = old_name + strlen(old_name) + 1;
 return handle_rename(fuse, handler, hdr, req, old_name, new_name);
 }

 case FUSE_OPEN: { /* open_in -> open_out */
 const struct fuse_open_in *req = data;
 return handle_open(fuse, handler, hdr, req);
 }

 case FUSE_READ: { /* read_in -> byte[] */
 const struct fuse_read_in *req = data;
 return handle_read(fuse, handler, hdr, req);
 }

 case FUSE_WRITE: { /* write_in, byte[write_in.size] -> write_out */
 const struct fuse_write_in *req = data;
 const void* buffer = (const __u8*)data + sizeof(*req);
 return handle_write(fuse, handler, hdr, req, buffer);
 }

 case FUSE_STATFS: { /* getattr_in -> attr_out */
 return handle_statfs(fuse, handler, hdr);
 }

 case FUSE_RELEASE: { /* release_in -> */
 const struct fuse_release_in *req = data;
 return handle_release(fuse, handler, hdr, req);
 }

 case FUSE_FSYNC:
 case FUSE_FSYNCDIR: {
 const struct fuse_fsync_in *req = data;
 return handle_fsync(fuse, handler, hdr, req);
 }

 case FUSE_FLUSH: {
 return handle_flush(fuse, handler, hdr);
 }

 case FUSE_OPENDIR: { /* open_in -> open_out */
 const struct fuse_open_in *req = data;
 return handle_opendir(fuse, handler, hdr, req);
 }

 case FUSE_READDIR: {
 const struct fuse_read_in *req = data;
 return handle_readdir(fuse, handler, hdr, req);
 }

 case FUSE_RELEASEDIR: { /* release_in -> */
 const struct fuse_release_in *req = data;
 return handle_releasedir(fuse, handler, hdr, req);
 }

 case FUSE_INIT: { /* init_in -> init_out */
 const struct fuse_init_in *req = data;
 return handle_init(fuse, handler, hdr, req);
 }

 default: {
        TRACE("[%d] NOTIMPL op=%d uniq=%"PRIx64" nid=%"PRIx64"\n",
                handler->token, hdr->opcode, hdr->unique, hdr->nodeid);
 return -ENOSYS;
 }
 }
}

static int handle_init(struct fuse* fuse, struct fuse_handler* handler,
 const struct fuse_in_header* hdr, const struct fuse_init_in* req)
{
 struct fuse_init_out out;
 size_t fuse_struct_size;

    TRACE("[%d] INIT ver=%d.%d maxread=%d flags=%x\n",
            handler->token, req->major, req->minor, req->max_readahead, req->flags);

 /* Kernel 2.6.16 is the first stable kernel with struct fuse_init_out
     * defined (fuse version 7.6). The structure is the same from 7.6 through
     * 7.22. Beginning with 7.23, the structure increased in size and added
     * new parameters.
     */
 if (req->major != FUSE_KERNEL_VERSION || req->minor < 6) {
        ERROR("Fuse kernel version mismatch: Kernel version %d.%d, Expected at least %d.6",
              req->major, req->minor, FUSE_KERNEL_VERSION);
 return -1;
 }

 /* We limit ourselves to 15 because we don't handle BATCH_FORGET yet */
    out.minor = MIN(req->minor, 15);
    fuse_struct_size = sizeof(out);
#if defined(FUSE_COMPAT_22_INIT_OUT_SIZE)
 /* FUSE_KERNEL_VERSION >= 23. */

 /* If the kernel only works on minor revs older than or equal to 22,
     * then use the older structure size since this code only uses the 7.22
     * version of the structure. */
 if (req->minor <= 22) {
        fuse_struct_size = FUSE_COMPAT_22_INIT_OUT_SIZE;
 }
#endif

    out.major = FUSE_KERNEL_VERSION;
    out.max_readahead = req->max_readahead;
    out.flags = FUSE_ATOMIC_O_TRUNC | FUSE_BIG_WRITES;
    out.max_background = 32;
    out.congestion_threshold = 32;
    out.max_write = MAX_WRITE;
    fuse_reply(fuse, hdr->unique, &out, fuse_struct_size);
 return NO_STATUS;
}

