FLAC_API FLAC__bool FLAC__stream_decoder_seek_absolute(FLAC__StreamDecoder *decoder, FLAC__uint64 sample)
{
	FLAC__uint64 length;

	FLAC__ASSERT(0 != decoder);

 if(
		decoder->protected_->state != FLAC__STREAM_DECODER_SEARCH_FOR_METADATA &&
		decoder->protected_->state != FLAC__STREAM_DECODER_READ_METADATA &&
		decoder->protected_->state != FLAC__STREAM_DECODER_SEARCH_FOR_FRAME_SYNC &&
		decoder->protected_->state != FLAC__STREAM_DECODER_READ_FRAME &&
		decoder->protected_->state != FLAC__STREAM_DECODER_END_OF_STREAM
 )
 return false;

 if(0 == decoder->private_->seek_callback)
 return false;

	FLAC__ASSERT(decoder->private_->seek_callback);
	FLAC__ASSERT(decoder->private_->tell_callback);
	FLAC__ASSERT(decoder->private_->length_callback);
	FLAC__ASSERT(decoder->private_->eof_callback);

 if(FLAC__stream_decoder_get_total_samples(decoder) > 0 && sample >= FLAC__stream_decoder_get_total_samples(decoder))
 return false;

	decoder->private_->is_seeking = true;

 /* turn off md5 checking if a seek is attempted */
	decoder->private_->do_md5_checking = false;

 /* get the file length (currently our algorithm needs to know the length so it's also an error to get FLAC__STREAM_DECODER_LENGTH_STATUS_UNSUPPORTED) */
 if(decoder->private_->length_callback(decoder, &length, decoder->private_->client_data) != FLAC__STREAM_DECODER_LENGTH_STATUS_OK) {
		decoder->private_->is_seeking = false;
 return false;
 }

 /* if we haven't finished processing the metadata yet, do that so we have the STREAMINFO, SEEK_TABLE, and first_frame_offset */
 if(
		decoder->protected_->state == FLAC__STREAM_DECODER_SEARCH_FOR_METADATA ||
		decoder->protected_->state == FLAC__STREAM_DECODER_READ_METADATA
 ) {
 if(!FLAC__stream_decoder_process_until_end_of_metadata(decoder)) {
 /* above call sets the state for us */
			decoder->private_->is_seeking = false;
 return false;
 }
 /* check this again in case we didn't know total_samples the first time */
 if(FLAC__stream_decoder_get_total_samples(decoder) > 0 && sample >= FLAC__stream_decoder_get_total_samples(decoder)) {
			decoder->private_->is_seeking = false;
 return false;
 }
 }

 {
 const FLAC__bool ok =
#if FLAC__HAS_OGG
			decoder->private_->is_ogg?
			seek_to_absolute_sample_ogg_(decoder, length, sample) :
#endif
			seek_to_absolute_sample_(decoder, length, sample)
 ;
		decoder->private_->is_seeking = false;
 return ok;
 }
}

FLAC_API FLAC__bool FLAC__stream_decoder_set_metadata_respond(FLAC__StreamDecoder *decoder, FLAC__MetadataType type)
{
	FLAC__ASSERT(0 != decoder);
	FLAC__ASSERT(0 != decoder->private_);
	FLAC__ASSERT(0 != decoder->protected_);
	FLAC__ASSERT((unsigned)type <= FLAC__MAX_METADATA_TYPE_CODE);
 /* double protection */
 if((unsigned)type > FLAC__MAX_METADATA_TYPE_CODE)
 return false;
 if(decoder->protected_->state != FLAC__STREAM_DECODER_UNINITIALIZED)
 return false;
	decoder->private_->metadata_filter[type] = true;
 if(type == FLAC__METADATA_TYPE_APPLICATION)
		decoder->private_->metadata_filter_ids_count = 0;
 return true;
}

FLAC__bool find_metadata_(FLAC__StreamDecoder *decoder)
{
	FLAC__uint32 x;
 unsigned i, id;
	FLAC__bool first = true;

	FLAC__ASSERT(FLAC__bitreader_is_consumed_byte_aligned(decoder->private_->input));

 for(i = id = 0; i < 4; ) {
 if(decoder->private_->cached) {
			x = (FLAC__uint32)decoder->private_->lookahead;
			decoder->private_->cached = false;
 }
 else {
 if(!FLAC__bitreader_read_raw_uint32(decoder->private_->input, &x, 8))
 return false; /* read_callback_ sets the state for us */
 }
 if(x == FLAC__STREAM_SYNC_STRING[i]) {
			first = true;
			i++;
			id = 0;
 continue;
 }

 if(id >= 3)
 return false;

 if(x == ID3V2_TAG_[id]) {
			id++;
			i = 0;
 if(id == 3) {
 if(!skip_id3v2_tag_(decoder))
 return false; /* skip_id3v2_tag_ sets the state for us */
 }
 continue;
 }
		id = 0;
 if(x == 0xff) { /* MAGIC NUMBER for the first 8 frame sync bits */
			decoder->private_->header_warmup[0] = (FLAC__byte)x;
 if(!FLAC__bitreader_read_raw_uint32(decoder->private_->input, &x, 8))
 return false; /* read_callback_ sets the state for us */

 /* we have to check if we just read two 0xff's in a row; the second may actually be the beginning of the sync code */
 /* else we have to check if the second byte is the end of a sync code */
 if(x == 0xff) { /* MAGIC NUMBER for the first 8 frame sync bits */
				decoder->private_->lookahead = (FLAC__byte)x;
				decoder->private_->cached = true;
 }
 else if(x >> 1 == 0x7c) { /* MAGIC NUMBER for the last 6 sync bits and reserved 7th bit */
				decoder->private_->header_warmup[1] = (FLAC__byte)x;
				decoder->protected_->state = FLAC__STREAM_DECODER_READ_FRAME;
 return true;
 }
 }
		i = 0;
 if(first) {
			send_error_to_client_(decoder, FLAC__STREAM_DECODER_ERROR_STATUS_LOST_SYNC);
			first = false;
 }
 }

	decoder->protected_->state = FLAC__STREAM_DECODER_READ_METADATA;
 return true;
}

FLAC__bool read_metadata_seektable_(FLAC__StreamDecoder *decoder, FLAC__bool is_last, unsigned length)
{
	FLAC__uint32 i, x;
	FLAC__uint64 xx;

	FLAC__ASSERT(FLAC__bitreader_is_consumed_byte_aligned(decoder->private_->input));

	decoder->private_->seek_table.type = FLAC__METADATA_TYPE_SEEKTABLE;
	decoder->private_->seek_table.is_last = is_last;
	decoder->private_->seek_table.length = length;

	decoder->private_->seek_table.data.seek_table.num_points = length / FLAC__STREAM_METADATA_SEEKPOINT_LENGTH;

 /* use realloc since we may pass through here several times (e.g. after seeking) */
 if(0 == (decoder->private_->seek_table.data.seek_table.points = safe_realloc_mul_2op_(decoder->private_->seek_table.data.seek_table.points, decoder->private_->seek_table.data.seek_table.num_points, /*times*/sizeof(FLAC__StreamMetadata_SeekPoint)))) {
		decoder->protected_->state = FLAC__STREAM_DECODER_MEMORY_ALLOCATION_ERROR;
 return false;
 }
 for(i = 0; i < decoder->private_->seek_table.data.seek_table.num_points; i++) {
 if(!FLAC__bitreader_read_raw_uint64(decoder->private_->input, &xx, FLAC__STREAM_METADATA_SEEKPOINT_SAMPLE_NUMBER_LEN))
 return false; /* read_callback_ sets the state for us */
		decoder->private_->seek_table.data.seek_table.points[i].sample_number = xx;

 if(!FLAC__bitreader_read_raw_uint64(decoder->private_->input, &xx, FLAC__STREAM_METADATA_SEEKPOINT_STREAM_OFFSET_LEN))
 return false; /* read_callback_ sets the state for us */
		decoder->private_->seek_table.data.seek_table.points[i].stream_offset = xx;

 if(!FLAC__bitreader_read_raw_uint32(decoder->private_->input, &x, FLAC__STREAM_METADATA_SEEKPOINT_FRAME_SAMPLES_LEN))
 return false; /* read_callback_ sets the state for us */
		decoder->private_->seek_table.data.seek_table.points[i].frame_samples = x;
 }
	length -= (decoder->private_->seek_table.data.seek_table.num_points * FLAC__STREAM_METADATA_SEEKPOINT_LENGTH);
 /* if there is a partial point left, skip over it */
 if(length > 0) {
 /*@@@ do a send_error_to_client_() here?  there's an argument for either way */
 if(!FLAC__bitreader_skip_byte_block_aligned_no_crc(decoder->private_->input, length))
 return false; /* read_callback_ sets the state for us */
 }

 return true;
}

FLAC__bool read_metadata_streaminfo_(FLAC__StreamDecoder *decoder, FLAC__bool is_last, unsigned length)
{
	FLAC__uint32 x;
 unsigned bits, used_bits = 0;

	FLAC__ASSERT(FLAC__bitreader_is_consumed_byte_aligned(decoder->private_->input));

	decoder->private_->stream_info.type = FLAC__METADATA_TYPE_STREAMINFO;
	decoder->private_->stream_info.is_last = is_last;
	decoder->private_->stream_info.length = length;

	bits = FLAC__STREAM_METADATA_STREAMINFO_MIN_BLOCK_SIZE_LEN;
 if(!FLAC__bitreader_read_raw_uint32(decoder->private_->input, &x, bits))
 return false; /* read_callback_ sets the state for us */
	decoder->private_->stream_info.data.stream_info.min_blocksize = x;
	used_bits += bits;

	bits = FLAC__STREAM_METADATA_STREAMINFO_MAX_BLOCK_SIZE_LEN;
 if(!FLAC__bitreader_read_raw_uint32(decoder->private_->input, &x, FLAC__STREAM_METADATA_STREAMINFO_MAX_BLOCK_SIZE_LEN))
 return false; /* read_callback_ sets the state for us */
	decoder->private_->stream_info.data.stream_info.max_blocksize = x;
	used_bits += bits;

	bits = FLAC__STREAM_METADATA_STREAMINFO_MIN_FRAME_SIZE_LEN;
 if(!FLAC__bitreader_read_raw_uint32(decoder->private_->input, &x, FLAC__STREAM_METADATA_STREAMINFO_MIN_FRAME_SIZE_LEN))
 return false; /* read_callback_ sets the state for us */
	decoder->private_->stream_info.data.stream_info.min_framesize = x;
	used_bits += bits;

	bits = FLAC__STREAM_METADATA_STREAMINFO_MAX_FRAME_SIZE_LEN;
 if(!FLAC__bitreader_read_raw_uint32(decoder->private_->input, &x, FLAC__STREAM_METADATA_STREAMINFO_MAX_FRAME_SIZE_LEN))
 return false; /* read_callback_ sets the state for us */
	decoder->private_->stream_info.data.stream_info.max_framesize = x;
	used_bits += bits;

	bits = FLAC__STREAM_METADATA_STREAMINFO_SAMPLE_RATE_LEN;
 if(!FLAC__bitreader_read_raw_uint32(decoder->private_->input, &x, FLAC__STREAM_METADATA_STREAMINFO_SAMPLE_RATE_LEN))
 return false; /* read_callback_ sets the state for us */
	decoder->private_->stream_info.data.stream_info.sample_rate = x;
	used_bits += bits;

	bits = FLAC__STREAM_METADATA_STREAMINFO_CHANNELS_LEN;
 if(!FLAC__bitreader_read_raw_uint32(decoder->private_->input, &x, FLAC__STREAM_METADATA_STREAMINFO_CHANNELS_LEN))
 return false; /* read_callback_ sets the state for us */
	decoder->private_->stream_info.data.stream_info.channels = x+1;
	used_bits += bits;

	bits = FLAC__STREAM_METADATA_STREAMINFO_BITS_PER_SAMPLE_LEN;
 if(!FLAC__bitreader_read_raw_uint32(decoder->private_->input, &x, FLAC__STREAM_METADATA_STREAMINFO_BITS_PER_SAMPLE_LEN))
 return false; /* read_callback_ sets the state for us */
	decoder->private_->stream_info.data.stream_info.bits_per_sample = x+1;
	used_bits += bits;

	bits = FLAC__STREAM_METADATA_STREAMINFO_TOTAL_SAMPLES_LEN;
 if(!FLAC__bitreader_read_raw_uint64(decoder->private_->input, &decoder->private_->stream_info.data.stream_info.total_samples, FLAC__STREAM_METADATA_STREAMINFO_TOTAL_SAMPLES_LEN))
 return false; /* read_callback_ sets the state for us */
	used_bits += bits;

 if(!FLAC__bitreader_read_byte_block_aligned_no_crc(decoder->private_->input, decoder->private_->stream_info.data.stream_info.md5sum, 16))
 return false; /* read_callback_ sets the state for us */
	used_bits += 16*8;

 /* skip the rest of the block */
	FLAC__ASSERT(used_bits % 8 == 0);
	length -= (used_bits / 8);
 if(!FLAC__bitreader_skip_byte_block_aligned_no_crc(decoder->private_->input, length))
 return false; /* read_callback_ sets the state for us */

 return true;
}

FLAC__bool read_subframe_(FLAC__StreamDecoder *decoder, unsigned channel, unsigned bps, FLAC__bool do_full_decode)
{
	FLAC__uint32 x;
	FLAC__bool wasted_bits;
 unsigned i;

 if(!FLAC__bitreader_read_raw_uint32(decoder->private_->input, &x, 8)) /* MAGIC NUMBER */
 return false; /* read_callback_ sets the state for us */

	wasted_bits = (x & 1);
	x &= 0xfe;

 if(wasted_bits) {
 unsigned u;
 if(!FLAC__bitreader_read_unary_unsigned(decoder->private_->input, &u))
 return false; /* read_callback_ sets the state for us */
		decoder->private_->frame.subframes[channel].wasted_bits = u+1;
		bps -= decoder->private_->frame.subframes[channel].wasted_bits;
 }
 else
		decoder->private_->frame.subframes[channel].wasted_bits = 0;

 /*
	 * Lots of magic numbers here
	 */
 if(x & 0x80) {
		send_error_to_client_(decoder, FLAC__STREAM_DECODER_ERROR_STATUS_LOST_SYNC);
		decoder->protected_->state = FLAC__STREAM_DECODER_SEARCH_FOR_FRAME_SYNC;
 return true;
 }
 else if(x == 0) {
 if(!read_subframe_constant_(decoder, channel, bps, do_full_decode))
 return false;
 }
 else if(x == 2) {
 if(!read_subframe_verbatim_(decoder, channel, bps, do_full_decode))
 return false;
 }
 else if(x < 16) {
		send_error_to_client_(decoder, FLAC__STREAM_DECODER_ERROR_STATUS_UNPARSEABLE_STREAM);
		decoder->protected_->state = FLAC__STREAM_DECODER_SEARCH_FOR_FRAME_SYNC;
 return true;
 }
 else if(x <= 24) {
 if(!read_subframe_fixed_(decoder, channel, bps, (x>>1)&7, do_full_decode))
 return false;
 if(decoder->protected_->state == FLAC__STREAM_DECODER_SEARCH_FOR_FRAME_SYNC) /* means bad sync or got corruption */
 return true;
 }
 else if(x < 64) {
		send_error_to_client_(decoder, FLAC__STREAM_DECODER_ERROR_STATUS_UNPARSEABLE_STREAM);
		decoder->protected_->state = FLAC__STREAM_DECODER_SEARCH_FOR_FRAME_SYNC;
 return true;
 }
 else {
 if(!read_subframe_lpc_(decoder, channel, bps, ((x>>1)&31)+1, do_full_decode))
 return false;
 if(decoder->protected_->state == FLAC__STREAM_DECODER_SEARCH_FOR_FRAME_SYNC) /* means bad sync or got corruption */
 return true;
 }

 if(wasted_bits && do_full_decode) {
		x = decoder->private_->frame.subframes[channel].wasted_bits;
 for(i = 0; i < decoder->private_->frame.header.blocksize; i++)
			decoder->private_->output[channel][i] <<= x;
 }

 return true;
}

FLAC__bool read_zero_padding_(FLAC__StreamDecoder *decoder)
{
 if(!FLAC__bitreader_is_consumed_byte_aligned(decoder->private_->input)) {
		FLAC__uint32 zero = 0;
 if(!FLAC__bitreader_read_raw_uint32(decoder->private_->input, &zero, FLAC__bitreader_bits_left_for_byte_alignment(decoder->private_->input)))
 return false; /* read_callback_ sets the state for us */
 if(zero != 0) {
			send_error_to_client_(decoder, FLAC__STREAM_DECODER_ERROR_STATUS_LOST_SYNC);
			decoder->protected_->state = FLAC__STREAM_DECODER_SEARCH_FOR_FRAME_SYNC;
 }
 }
 return true;
}

int aacDecoder_drcMarkPayload (
    HANDLE_AAC_DRC self,
    HANDLE_FDK_BITSTREAM bs,
    AACDEC_DRC_PAYLOAD_TYPE type )
{
  UINT bsStartPos;
 int  i, numBands = 1, bitCnt = 0;

 if (self == NULL) {
 return 0;
 }

  bsStartPos = FDKgetValidBits(bs);

 switch (type) {
 case MPEG_DRC_EXT_DATA:
 {
      bitCnt = 4;

 if (FDKreadBits(bs,1)) { /* pce_tag_present */
 FDKreadBits(bs,8); /* pce_instance_tag + drc_tag_reserved_bits */
        bitCnt+=8;
 }

 if (FDKreadBits(bs,1)) { /* excluded_chns_present */
 FDKreadBits(bs,7); /* exclude mask [0..7] */
        bitCnt+=8;
 while (FDKreadBits(bs,1)) { /* additional_excluded_chns */
 FDKreadBits(bs,7); /* exclude mask [x..y] */
          bitCnt+=8;
 }
 }

 if (FDKreadBits(bs,1)) { /* drc_bands_present */
        numBands += FDKreadBits(bs, 4); /* drc_band_incr */
 FDKreadBits(bs,4); /* reserved */
        bitCnt+=8;
 for (i = 0; i < numBands; i++) {
 FDKreadBits(bs,8); /* drc_band_top[i] */
          bitCnt+=8;
 }
 }

 if (FDKreadBits(bs,1)) { /* prog_ref_level_present */
 FDKreadBits(bs,8); /* prog_ref_level + prog_ref_level_reserved_bits */
        bitCnt+=8;
 }

 for (i = 0; i < numBands; i++) {
 FDKreadBits(bs,8); /* dyn_rng_sgn[i] + dyn_rng_ctl[i] */
        bitCnt+=8;
 }

 if ( (self->numPayloads < MAX_DRC_THREADS)
 && ((INT)FDKgetValidBits(bs) >= 0) )
 {
        self->drcPayloadPosition[self->numPayloads++] = bsStartPos;
 }
 }
 break;

 case DVB_DRC_ANC_DATA:
      bitCnt += 8;
 /* check sync word */
 if (FDKreadBits(bs, 8) == DVB_ANC_DATA_SYNC_BYTE)
 {
 int dmxLevelsPresent, compressionPresent;
 int coarseGrainTcPresent, fineGrainTcPresent;

 /* bs_info field */ 
 FDKreadBits(bs, 8); /* mpeg_audio_type, dolby_surround_mode, presentation_mode */
        bitCnt+=8;

 /* Evaluate ancillary_data_status */
 FDKreadBits(bs, 3); /* reserved, set to 0 */
        dmxLevelsPresent = FDKreadBits(bs, 1); /* downmixing_levels_MPEG4_status */
 FDKreadBits(bs, 1); /* reserved, set to 0 */
        compressionPresent   = FDKreadBits(bs, 1); /* audio_coding_mode_and_compression status */
        coarseGrainTcPresent = FDKreadBits(bs, 1); /* coarse_grain_timecode_status */
        fineGrainTcPresent   = FDKreadBits(bs, 1); /* fine_grain_timecode_status */
        bitCnt+=8;

 /* MPEG4 downmixing levels */
 if (dmxLevelsPresent) {
 FDKreadBits(bs, 8); /* downmixing_levels_MPEG4 */
          bitCnt+=8;
 }
 /* audio coding mode and compression status */
 if (compressionPresent) {
 FDKreadBits(bs, 16); /* audio_coding_mode, Compression_value */
          bitCnt+=16;
 }
 /* coarse grain timecode */
 if (coarseGrainTcPresent) {
 FDKreadBits(bs, 16); /* coarse_grain_timecode */
          bitCnt+=16;
 }
 /* fine grain timecode */
 if (fineGrainTcPresent) {
 FDKreadBits(bs, 16); /* fine_grain_timecode */
          bitCnt+=16;
 }
 if ( !self->dvbAncDataAvailable
 && ((INT)FDKgetValidBits(bs) >= 0) )
 {
          self->dvbAncDataPosition  = bsStartPos;
          self->dvbAncDataAvailable = 1;
 }
 }
 break;

 default:
 break;
 }

 return (bitCnt);
}

static void dump_log_file(
 log_t* log, pid_t pid, const char* filename, unsigned int tail) {
 bool first = true;
 struct logger_list* logger_list;

 if (!log->should_retrieve_logcat) {
 return;
 }

  logger_list = android_logger_list_open(
      android_name_to_log_id(filename), O_RDONLY | O_NONBLOCK, tail, pid);

 if (!logger_list) {
    ALOGE("Unable to open %s: %s\n", filename, strerror(errno));
 return;
 }

 struct log_msg log_entry;

 while (true) {
 ssize_t actual = android_logger_list_read(logger_list, &log_entry);
 struct logger_entry* entry;

 if (actual < 0) {
 if (actual == -EINTR) {
 continue;
 } else if (actual == -EAGAIN) {
 break;
 } else {
        _LOG(log, logtype::ERROR, "Error while reading log: %s\n",
          strerror(-actual));
 break;
 }
 } else if (actual == 0) {
      _LOG(log, logtype::ERROR, "Got zero bytes while reading log: %s\n",
        strerror(errno));
 break;
 }


    entry = &log_entry.entry_v1;

 if (first) {
      _LOG(log, logtype::LOGS, "--------- %slog %s\n",
        tail ? "tail end of " : "", filename);
      first = false;
 }

 static const char* kPrioChars = "!.VDIWEFS";
 unsigned hdr_size = log_entry.entry.hdr_size;
 if (!hdr_size) {
      hdr_size = sizeof(log_entry.entry_v1);
 }
 char* msg = reinterpret_cast<char*>(log_entry.buf) + hdr_size;

 char timeBuf[32];
 time_t sec = static_cast<time_t>(entry->sec);
 struct tm tmBuf;
 struct tm* ptm;
    ptm = localtime_r(&sec, &tmBuf);
    strftime(timeBuf, sizeof(timeBuf), "%m-%d %H:%M:%S", ptm);

 if (log_entry.id() == LOG_ID_EVENTS) {
 if (!g_eventTagMap) {
        g_eventTagMap = android_openEventTagMap(EVENT_TAG_MAP_FILE);
 }
 AndroidLogEntry e;
 char buf[512];
      android_log_processBinaryLogBuffer(entry, &e, g_eventTagMap, buf, sizeof(buf));
      _LOG(log, logtype::LOGS, "%s.%03d %5d %5d %c %-8s: %s\n",
         timeBuf, entry->nsec / 1000000, entry->pid, entry->tid,
 'I', e.tag, e.message);
 continue;
 }

 unsigned char prio = msg[0];
 char* tag = msg + 1;
    msg = tag + strlen(tag) + 1;

 char* nl = msg + strlen(msg) - 1;
 while (nl >= msg && *nl == '\n') {
 *nl-- = '\0';
 }

 char prioChar = (prio < strlen(kPrioChars) ? kPrioChars[prio] : '?');

 do {
      nl = strchr(msg, '\n');
 if (nl) {
 *nl = '\0';
 ++nl;
 }

      _LOG(log, logtype::LOGS, "%s.%03d %5d %5d %c %-8s: %s\n",
         timeBuf, entry->nsec / 1000000, entry->pid, entry->tid,
         prioChar, tag, msg);
 } while ((msg = nl));
 }

  android_logger_list_free(logger_list);
}

virtual status_t initCheck() const {
Parcel data, reply;
       data.writeInterfaceToken(IDrm::getInterfaceDescriptor());
status_t status = remote()->transact(INIT_CHECK, data, &reply);
if (status != OK) {
return status;
}

return reply.readInt32();
}

virtual bool isCryptoSchemeSupported(const uint8_t uuid[16], const String8 &mimeType) {
Parcel data, reply;
       data.writeInterfaceToken(IDrm::getInterfaceDescriptor());
       data.write(uuid, 16);
       data.writeString8(mimeType);
status_t status = remote()->transact(IS_CRYPTO_SUPPORTED, data, &reply);
if (status != OK) {
           ALOGE("isCryptoSchemeSupported: binder call failed: %d", status);
return false;
}

return reply.readInt32() != 0;
}

virtual status_t releaseSecureStops(Vector<uint8_t> const &ssRelease) {
Parcel data, reply;
       data.writeInterfaceToken(IDrm::getInterfaceDescriptor());

       writeVector(data, ssRelease);
status_t status = remote()->transact(RELEASE_SECURE_STOPS, data, &reply);
if (status != OK) {
return status;
}

return reply.readInt32();
}

void BnDrm::writeVector(Parcel *reply, Vector<uint8_t> const &vector) const {
    reply->writeInt32(vector.size());
    reply->write(vector.array(), vector.size());
}

virtual status_t fillBuffer(node_id node, buffer_id buffer) {
Parcel data, reply;
       data.writeInterfaceToken(IOMX::getInterfaceDescriptor());
       data.writeInt32((int32_t)node);
       data.writeInt32((int32_t)buffer);
       remote()->transact(FILL_BUFFER, data, &reply);

return reply.readInt32();
}

virtual void onMessage(const omx_message &msg) {
Parcel data, reply;
       data.writeInterfaceToken(IOMXObserver::getInterfaceDescriptor());
       data.write(&msg, sizeof(msg));

       ALOGV("onMessage writing message %d, size %zu", msg.type, sizeof(msg));

       remote()->transact(OBSERVER_ON_MSG, data, &reply, IBinder::FLAG_ONEWAY);
}

virtual status_t useBuffer(
           node_id node, OMX_U32 port_index, const sp<IMemory> &params,
           buffer_id *buffer) {
Parcel data, reply;
       data.writeInterfaceToken(IOMX::getInterfaceDescriptor());
       data.writeInt32((int32_t)node);
       data.writeInt32(port_index);
       data.writeStrongBinder(params->asBinder());
       remote()->transact(USE_BUFFER, data, &reply);

status_t err = reply.readInt32();
if (err != OK) {
*buffer = 0;

return err;
}

*buffer = (buffer_id)reply.readInt32();

return err;
}

get_lease(struct dhcp_lease *lease, const struct dhcp_message *dhcp)
{
 struct timeval now;

	lease->cookie = dhcp->cookie;
 /* BOOTP does not set yiaddr for replies when ciaddr is set. */
 if (dhcp->yiaddr)
		lease->addr.s_addr = dhcp->yiaddr;
 else
		lease->addr.s_addr = dhcp->ciaddr;
 if (get_option_addr(&lease->net, dhcp, DHO_SUBNETMASK) == -1)
		lease->net.s_addr = get_netmask(lease->addr.s_addr);
 if (get_option_addr(&lease->brd, dhcp, DHO_BROADCAST) == -1)
		lease->brd.s_addr = lease->addr.s_addr | ~lease->net.s_addr;
 if (get_option_uint32(&lease->leasetime, dhcp, DHO_LEASETIME) == 0) {
 /* Ensure that we can use the lease */
		get_monotonic(&now);
 if (now.tv_sec + (time_t)lease->leasetime < now.tv_sec)
			lease->leasetime = ~0U; /* Infinite lease */
 } else
		lease->leasetime = ~0U; /* Default to infinite lease */
 if (get_option_uint32(&lease->renewaltime, dhcp, DHO_RENEWALTIME) != 0)
		lease->renewaltime = 0;
 if (get_option_uint32(&lease->rebindtime, dhcp, DHO_REBINDTIME) != 0)
		lease->rebindtime = 0;
 if (get_option_addr(&lease->server, dhcp, DHO_SERVERID) != 0)
		lease->server.s_addr = INADDR_ANY;
}

tBTM_STATUS BTM_SetEncryption (BD_ADDR bd_addr, tBT_TRANSPORT transport, tBTM_SEC_CBACK *p_callback,
 void *p_ref_data)
{
    tBTM_SEC_DEV_REC  *p_dev_rec;
    tBTM_STATUS       rc;
#if BLE_INCLUDED == TRUE
   tACL_CONN         *p = btm_bda_to_acl(bd_addr, transport);
#endif

    p_dev_rec = btm_find_dev (bd_addr);

 if (!p_dev_rec ||
 (transport == BT_TRANSPORT_BR_EDR && p_dev_rec->hci_handle == BTM_SEC_INVALID_HANDLE)
#if BLE_INCLUDED == TRUE
 || (transport == BT_TRANSPORT_LE && p_dev_rec->ble_hci_handle == BTM_SEC_INVALID_HANDLE)
#endif
 )
 {
 /* Connection should be up and runnning */
        BTM_TRACE_WARNING ("Security Manager: BTM_SetEncryption not connected");

 if (p_callback)
 (*p_callback) (bd_addr, transport, p_ref_data, BTM_WRONG_MODE);

 return(BTM_WRONG_MODE);
 }

 if ((transport == BT_TRANSPORT_BR_EDR &&
 (p_dev_rec->sec_flags &  BTM_SEC_ENCRYPTED))
#if BLE_INCLUDED == TRUE && SMP_INCLUDED == TRUE
 || (transport == BT_TRANSPORT_LE &&
 (p_dev_rec->sec_flags & BTM_SEC_LE_ENCRYPTED))
#endif
 )
 {
        BTM_TRACE_EVENT ("Security Manager: BTM_SetEncryption already encrypted");

 if (p_callback)
 (*p_callback) (bd_addr, transport, p_ref_data, BTM_SUCCESS);

 return(BTM_SUCCESS);
 }

 if (p_dev_rec->p_callback)
 {
 /* Connection should be up and runnning */
        BTM_TRACE_WARNING ("Security Manager: BTM_SetEncryption busy");

 if (p_callback)
 (*p_callback) (bd_addr, transport, p_ref_data, BTM_BUSY);

 return(BTM_BUSY);
 }

    p_dev_rec->p_callback        = p_callback;
    p_dev_rec->p_ref_data        = p_ref_data;
    p_dev_rec->security_required |= (BTM_SEC_IN_AUTHENTICATE | BTM_SEC_IN_ENCRYPT);
    p_dev_rec->is_originator     = FALSE;

    BTM_TRACE_API ("Security Manager: BTM_SetEncryption Handle:%d State:%d Flags:0x%x Required:0x%x",
                    p_dev_rec->hci_handle, p_dev_rec->sec_state, p_dev_rec->sec_flags,
                    p_dev_rec->security_required);

#if BLE_INCLUDED == TRUE && SMP_INCLUDED == TRUE
 if (transport == BT_TRANSPORT_LE)
 {
        rc = btm_ble_set_encryption(bd_addr, p_ref_data, p->link_role);
 }
 else
#endif

        rc = btm_sec_execute_procedure (p_dev_rec);

 if (rc != BTM_CMD_STARTED && rc != BTM_BUSY)
 {
 if (p_callback)
 {
            p_dev_rec->p_callback = NULL;
 (*p_callback) (bd_addr, transport, p_dev_rec->p_ref_data, rc);
 }
 }
 return(rc);
}

static BOOLEAN btm_dev_encrypted (tBTM_SEC_DEV_REC *p_dev_rec)
{
 if(p_dev_rec->sec_flags & BTM_SEC_ENCRYPTED)
 {
 return(TRUE);
 }
 return(FALSE);
}

void btm_rem_oob_req (UINT8 *p)
{
    UINT8 *p_bda;
    tBTM_SP_RMT_OOB  evt_data;
    tBTM_SEC_DEV_REC *p_dev_rec;
    BT_OCTET16      c;
    BT_OCTET16      r;

    p_bda = evt_data.bd_addr;

    STREAM_TO_BDADDR (p_bda, p);

    BTM_TRACE_EVENT ("btm_rem_oob_req() BDA: %02x:%02x:%02x:%02x:%02x:%02x",
                      p_bda[0], p_bda[1], p_bda[2], p_bda[3], p_bda[4], p_bda[5]);

 if ( (NULL != (p_dev_rec = btm_find_dev (p_bda))) &&
         btm_cb.api.p_sp_callback)
 {
        memcpy (evt_data.bd_addr, p_dev_rec->bd_addr, BD_ADDR_LEN);
        memcpy (evt_data.dev_class, p_dev_rec->dev_class, DEV_CLASS_LEN);
        BCM_STRNCPY_S((char *)evt_data.bd_name, sizeof(evt_data.bd_name), (char *)p_dev_rec->sec_bd_name, BTM_MAX_REM_BD_NAME_LEN+1);
        evt_data.bd_name[BTM_MAX_REM_BD_NAME_LEN] = 0;

        btm_sec_change_pairing_state(BTM_PAIR_STATE_WAIT_LOCAL_OOB_RSP);
 if ((*btm_cb.api.p_sp_callback) (BTM_SP_RMT_OOB_EVT, (tBTM_SP_EVT_DATA *)&evt_data) == BTM_NOT_AUTHORIZED)
 {
            BTM_RemoteOobDataReply(TRUE, p_bda, c, r);
 }
 return;
 }

 /* something bad. we can only fail this connection */
    btm_cb.acl_disc_reason = HCI_ERR_HOST_REJECT_SECURITY;
    btsnd_hcic_rem_oob_neg_reply (p_bda);
}

tBTM_STATUS btm_sec_bond_by_transport (BD_ADDR bd_addr, tBT_TRANSPORT transport,
                                       UINT8 pin_len, UINT8 *p_pin, UINT32 trusted_mask[])
{
    tBTM_SEC_DEV_REC *p_dev_rec;
    tBTM_STATUS      status;
    UINT8            *p_features;
    UINT8            ii;
    tACL_CONN        *p= btm_bda_to_acl(bd_addr, transport);
    BTM_TRACE_API ("btm_sec_bond_by_transport BDA: %02x:%02x:%02x:%02x:%02x:%02x",
                    bd_addr[0], bd_addr[1], bd_addr[2], bd_addr[3], bd_addr[4], bd_addr[5]);

    BTM_TRACE_DEBUG("btm_sec_bond_by_transport: Transport used %d" , transport);


 /* Other security process is in progress */
 if (btm_cb.pairing_state != BTM_PAIR_STATE_IDLE)
 {
        BTM_TRACE_ERROR ("BTM_SecBond: already busy in state: %s", btm_pair_state_descr(btm_cb.pairing_state));
 return(BTM_WRONG_MODE);
 }

 if ((p_dev_rec = btm_find_or_alloc_dev (bd_addr)) == NULL)
 {
 return(BTM_NO_RESOURCES);
 }

    BTM_TRACE_DEBUG ("before update sec_flags=0x%x", p_dev_rec->sec_flags);

 /* Finished if connection is active and already paired */
 if ( ((p_dev_rec->hci_handle != BTM_SEC_INVALID_HANDLE) && transport == BT_TRANSPORT_BR_EDR
 && (p_dev_rec->sec_flags & BTM_SEC_AUTHENTICATED))
#if (BLE_INCLUDED == TRUE)
 ||((p_dev_rec->ble_hci_handle != BTM_SEC_INVALID_HANDLE) && transport == BT_TRANSPORT_LE
 && (p_dev_rec->sec_flags & BTM_SEC_LE_AUTHENTICATED))
#endif

 )
 {
        BTM_TRACE_WARNING("BTM_SecBond -> Already Paired");
 return(BTM_SUCCESS);
 }

 /* Tell controller to get rid of the link key if it has one stored */
 if ((BTM_DeleteStoredLinkKey (bd_addr, NULL)) != BTM_SUCCESS)
 return(BTM_NO_RESOURCES);

 /* Save the PIN code if we got a valid one */
 if (p_pin && (pin_len <= PIN_CODE_LEN) && (pin_len != 0))
 {
        btm_cb.pin_code_len = pin_len;
        memcpy (btm_cb.pin_code, p_pin, PIN_CODE_LEN);
 }

    memcpy (btm_cb.pairing_bda, bd_addr, BD_ADDR_LEN);

    btm_cb.pairing_flags = BTM_PAIR_FLAGS_WE_STARTED_DD;

    p_dev_rec->security_required = BTM_SEC_OUT_AUTHENTICATE;
    p_dev_rec->is_originator     = TRUE;
 if (trusted_mask)
        BTM_SEC_COPY_TRUSTED_DEVICE(trusted_mask, p_dev_rec->trusted_mask);

#if BLE_INCLUDED == TRUE && SMP_INCLUDED == TRUE
 if (transport == BT_TRANSPORT_LE)
 {
        p_dev_rec->sec_flags &= ~ BTM_SEC_LE_MASK;

 if (SMP_Pair(bd_addr) == SMP_STARTED)
 {
            btm_cb.pairing_flags |= BTM_PAIR_FLAGS_LE_ACTIVE;
            p_dev_rec->sec_state = BTM_SEC_STATE_AUTHENTICATING;
            btm_sec_change_pairing_state (BTM_PAIR_STATE_WAIT_AUTH_COMPLETE);
 return BTM_CMD_STARTED;
 }

        btm_cb.pairing_flags = 0;
 return(BTM_NO_RESOURCES);
 }
#endif

    p_dev_rec->sec_flags &= ~(BTM_SEC_LINK_KEY_KNOWN | BTM_SEC_AUTHENTICATED | BTM_SEC_ENCRYPTED
 | BTM_SEC_ROLE_SWITCHED  | BTM_SEC_LINK_KEY_AUTHED);


    BTM_TRACE_DEBUG ("after update sec_flags=0x%x", p_dev_rec->sec_flags);
 if (!HCI_SIMPLE_PAIRING_SUPPORTED(btm_cb.devcb.local_lmp_features[HCI_EXT_FEATURES_PAGE_0]))
 {
 /* The special case when we authenticate keyboard.  Set pin type to fixed */
 /* It would be probably better to do it from the application, but it is */
 /* complicated */
 if (((p_dev_rec->dev_class[1] & BTM_COD_MAJOR_CLASS_MASK) == BTM_COD_MAJOR_PERIPHERAL)
 && (p_dev_rec->dev_class[2] & BTM_COD_MINOR_KEYBOARD)
 && (btm_cb.cfg.pin_type != HCI_PIN_TYPE_FIXED))
 {
            btm_cb.pin_type_changed = TRUE;
            btsnd_hcic_write_pin_type (HCI_PIN_TYPE_FIXED);
 }
 }

 for (ii = 0; ii <= HCI_EXT_FEATURES_PAGE_MAX; ii++)
 {
        p_features = p_dev_rec->features[ii];
        BTM_TRACE_EVENT("  remote_features page[%1d] = %02x-%02x-%02x-%02x",
                         ii, p_features[0], p_features[1], p_features[2], p_features[3]);
        BTM_TRACE_EVENT("                              %02x-%02x-%02x-%02x",
                             p_features[4], p_features[5], p_features[6], p_features[7]);
 }

    BTM_TRACE_EVENT ("BTM_SecBond: Remote sm4: 0x%x  HCI Handle: 0x%04x", p_dev_rec->sm4, p_dev_rec->hci_handle);

#if BTM_SEC_FORCE_RNR_FOR_DBOND == TRUE
    p_dev_rec->sec_flags &= ~BTM_SEC_NAME_KNOWN;
#endif

 /* If connection already exists... */
 if (p && p->hci_handle != BTM_SEC_INVALID_HANDLE)
 {
 if (!btm_sec_start_authentication (p_dev_rec))
 return(BTM_NO_RESOURCES);

        btm_sec_change_pairing_state (BTM_PAIR_STATE_WAIT_PIN_REQ);

 /* Mark lcb as bonding */
        l2cu_update_lcb_4_bonding (bd_addr, TRUE);
 return(BTM_CMD_STARTED);
 }

    BTM_TRACE_DEBUG ("sec mode: %d sm4:x%x", btm_cb.security_mode, p_dev_rec->sm4);
 if (!HCI_SIMPLE_PAIRING_SUPPORTED(btm_cb.devcb.local_lmp_features[HCI_EXT_FEATURES_PAGE_0])
 || (p_dev_rec->sm4 == BTM_SM4_KNOWN))
 {
 if ( btm_sec_check_prefetch_pin (p_dev_rec) )
 return(BTM_CMD_STARTED);
 }
 if (BTM_SEC_MODE_SP == btm_cb.security_mode && BTM_SEC_IS_SM4_UNKNOWN(p_dev_rec->sm4))
 {
 /* local is 2.1 and peer is unknown */
 if ((p_dev_rec->sm4 & BTM_SM4_CONN_PEND) == 0)
 {
 /* we are not accepting connection request from peer
             * -> RNR (to learn if peer is 2.1)
             * RNR when no ACL causes HCI_RMT_HOST_SUP_FEAT_NOTIFY_EVT */
            btm_sec_change_pairing_state (BTM_PAIR_STATE_GET_REM_NAME);
            BTM_ReadRemoteDeviceName(bd_addr, NULL, BT_TRANSPORT_BR_EDR);
 }
 else
 {
 /* We are accepting connection request from peer */
            btm_sec_change_pairing_state (BTM_PAIR_STATE_WAIT_PIN_REQ);
 }
        BTM_TRACE_DEBUG ("State:%s sm4: 0x%x sec_state:%d",
            btm_pair_state_descr (btm_cb.pairing_state), p_dev_rec->sm4, p_dev_rec->sec_state);
 return BTM_CMD_STARTED;
 }

 /* both local and peer are 2.1  */
    status = btm_sec_dd_create_conn(p_dev_rec);

 if (status != BTM_CMD_STARTED)
 {
        btm_sec_change_pairing_state (BTM_PAIR_STATE_IDLE);
 }

 return status;
}

void btm_sec_conn_req (UINT8 *bda, UINT8 *dc)
{
    tBTM_SEC_DEV_REC  *p_dev_rec = btm_find_dev (bda);

 /* Some device may request a connection before we are done with the HCI_Reset sequence */
 if (btm_cb.devcb.state != BTM_DEV_STATE_READY)
 {
        BTM_TRACE_EVENT ("Security Manager: connect request when device not ready");
        btsnd_hcic_reject_conn (bda, HCI_ERR_HOST_REJECT_DEVICE);
 return;
 }

 /* Security guys wants us not to allow connection from not paired devices */

 /* Check if connection is allowed for only paired devices */
 if (btm_cb.connect_only_paired)
 {
 if (!p_dev_rec || !(p_dev_rec->sec_flags & BTM_SEC_LINK_KEY_AUTHED))
 {
            BTM_TRACE_EVENT ("Security Manager: connect request from non-paired device");
            btsnd_hcic_reject_conn (bda, HCI_ERR_HOST_REJECT_DEVICE);
 return;
 }
 }

#if BTM_ALLOW_CONN_IF_NONDISCOVER == FALSE
 /* If non-discoverable, only allow known devices to connect */
 if (btm_cb.btm_inq_vars.discoverable_mode == BTM_NON_DISCOVERABLE)
 {
 if (!p_dev_rec)
 {
            BTM_TRACE_EVENT ("Security Manager: connect request from not paired device");
            btsnd_hcic_reject_conn (bda, HCI_ERR_HOST_REJECT_DEVICE);
 return;
 }
 }
#endif

 /* Host can be registered to verify comming BDA or DC */
 if (btm_cb.p_conn_filter_cb)
 {
 if (!(* btm_cb.p_conn_filter_cb) (bda, dc))
 {
            BTM_TRACE_EVENT ("Security Manager: connect request did not pass filter");

 /* incomming call did not pass connection filters.  Reject */
            btsnd_hcic_reject_conn (bda, HCI_ERR_HOST_REJECT_DEVICE);
 return;
 }
 }

 if ((btm_cb.pairing_state != BTM_PAIR_STATE_IDLE)
 &&(btm_cb.pairing_flags & BTM_PAIR_FLAGS_WE_STARTED_DD)
 &&(!memcmp (btm_cb.pairing_bda, bda, BD_ADDR_LEN)))
 {
        BTM_TRACE_EVENT ("Security Manager: reject connect request from bonding device");

 /* incoming connection from bonding device is rejected */
        btm_cb.pairing_flags |= BTM_PAIR_FLAGS_REJECTED_CONNECT;
        btsnd_hcic_reject_conn (bda, HCI_ERR_HOST_REJECT_DEVICE);
 return;
 }

 /* Host is not interested or approved connection.  Save BDA and DC and */
 /* pass request to L2CAP */
    memcpy (btm_cb.connecting_bda, bda, BD_ADDR_LEN);
    memcpy (btm_cb.connecting_dc,  dc,  DEV_CLASS_LEN);

 if (l2c_link_hci_conn_req (bda))
 {
 if (!p_dev_rec)
 {
 /* accept the connection -> allocate a device record */
            p_dev_rec = btm_sec_alloc_dev (bda);
 }
 if (p_dev_rec)
 {
            p_dev_rec->sm4 |= BTM_SM4_CONN_PEND;
 }
 }
}

tBTM_STATUS btm_sec_disconnect (UINT16 handle, UINT8 reason)
{
    tBTM_SEC_DEV_REC  *p_dev_rec = btm_find_dev_by_handle (handle);

 /* In some weird race condition we may not have a record */
 if (!p_dev_rec)
 {
        btsnd_hcic_disconnect (handle, reason);
 return(BTM_SUCCESS);
 }

 /* If we are in the process of bonding we need to tell client that auth failed */
 if ( (btm_cb.pairing_state != BTM_PAIR_STATE_IDLE)
 && (memcmp (btm_cb.pairing_bda, p_dev_rec->bd_addr, BD_ADDR_LEN) == 0)
 && (btm_cb.pairing_flags & BTM_PAIR_FLAGS_WE_STARTED_DD) )
 {
 /* we are currently doing bonding.  Link will be disconnected when done */
        btm_cb.pairing_flags |= BTM_PAIR_FLAGS_DISC_WHEN_DONE;
 return(BTM_BUSY);
 }

 return(btm_sec_send_hci_disconnect(p_dev_rec, reason, handle));
}

void btm_sec_link_key_notification (UINT8 *p_bda, UINT8 *p_link_key, UINT8 key_type)
{
    tBTM_SEC_DEV_REC *p_dev_rec = btm_find_or_alloc_dev (p_bda);
    BOOLEAN          we_are_bonding = FALSE;

    BTM_TRACE_EVENT ("btm_sec_link_key_notification()  BDA:%04x%08x, TYPE: %d",
 (p_bda[0]<<8)+p_bda[1], (p_bda[2]<<24)+(p_bda[3]<<16)+(p_bda[4]<<8)+p_bda[5],
                      key_type);

 /* If connection was made to do bonding restore link security if changed */
    btm_restore_mode();

 /* Override the key type if version is pre-1.1 */
 if (btm_cb.devcb.local_version.hci_version < HCI_VERSION_1_1)
        p_dev_rec->link_key_type = BTM_LKEY_TYPE_IGNORE;
 if (key_type != BTM_LKEY_TYPE_CHANGED_COMB)
        p_dev_rec->link_key_type = key_type;

    p_dev_rec->sec_flags |= BTM_SEC_LINK_KEY_KNOWN;
#if (BLE_INCLUDED == TRUE)
 /* BR/EDR connection, update the encryption key size to be 16 as always */
    p_dev_rec->enc_key_size = 16;
#endif
    memcpy (p_dev_rec->link_key, p_link_key, LINK_KEY_LEN);

 if ( (btm_cb.pairing_state != BTM_PAIR_STATE_IDLE)
 && (memcmp (btm_cb.pairing_bda, p_bda, BD_ADDR_LEN) == 0) )
 {
 if (btm_cb.pairing_flags & BTM_PAIR_FLAGS_WE_STARTED_DD)
            we_are_bonding = TRUE;
 else
            btm_sec_change_pairing_state (BTM_PAIR_STATE_IDLE);
 }

 /* If name is not known at this point delay calling callback until the name is   */
 /* resolved. Unless it is a HID Device and we really need to send all link keys. */
 if ((!(p_dev_rec->sec_flags & BTM_SEC_NAME_KNOWN)
 && ((p_dev_rec->dev_class[1] & BTM_COD_MAJOR_CLASS_MASK) != BTM_COD_MAJOR_PERIPHERAL)) )
 {
        BTM_TRACE_EVENT ("btm_sec_link_key_notification()  Delayed BDA: %08x%04x Type:%d",
 (p_bda[0]<<24) + (p_bda[1]<<16) + (p_bda[2]<<8) + p_bda[3], (p_bda[4] << 8) + p_bda[5], key_type);

        p_dev_rec->link_key_not_sent = TRUE;

 /* If it is for bonding nothing else will follow, so we need to start name resolution */
 if (we_are_bonding)
 {
 if (!(btsnd_hcic_rmt_name_req (p_bda, HCI_PAGE_SCAN_REP_MODE_R1, HCI_MANDATARY_PAGE_SCAN_MODE, 0)))
                btm_inq_rmt_name_failed();
 }

        BTM_TRACE_EVENT ("rmt_io_caps:%d, sec_flags:x%x, dev_class[1]:x%02x", p_dev_rec->rmt_io_caps, p_dev_rec->sec_flags, p_dev_rec->dev_class[1])
 return;
 }

 /* If its not us who perform authentication, we should tell stackserver */
 /* that some authentication has been completed                          */
 /* This is required when different entities receive link notification and auth complete */
 if (!(p_dev_rec->security_required & BTM_SEC_OUT_AUTHENTICATE))
 {
 if (btm_cb.api.p_auth_complete_callback)
 (*btm_cb.api.p_auth_complete_callback) (p_dev_rec->bd_addr, p_dev_rec->dev_class,
                                                    p_dev_rec->sec_bd_name, HCI_SUCCESS);
 }

 /* We will save link key only if the user authorized it - BTE report link key in all cases */
#ifdef BRCM_NONE_BTE
 if (p_dev_rec->sec_flags & BTM_SEC_LINK_KEY_AUTHED)
#endif
 {
 if (btm_cb.api.p_link_key_callback)
 {
 (*btm_cb.api.p_link_key_callback) (p_bda, p_dev_rec->dev_class,  p_dev_rec->sec_bd_name,
                                               p_link_key, p_dev_rec->link_key_type);
 }
 }
}

void btm_sec_mkey_comp_event (UINT16 handle, UINT8 status, UINT8 key_flg)
{
    tBTM_SEC_DEV_REC  *p_dev_rec = btm_find_dev_by_handle (handle);
    UINT8 bd_addr[BD_ADDR_LEN] = { 0xff, 0xff, 0xff, 0xff, 0xff, 0xff} ;

    BTM_TRACE_EVENT ("Security Manager: mkey comp status:%d State:%d",
                      status, (p_dev_rec) ? p_dev_rec->sec_state : 0);

 /* If encryption setup failed, notify the waiting layer */
 /* There is no next procedure or start of procedure failed, notify the waiting layer */
 if (btm_cb.mkey_cback)
 {
 if (!p_dev_rec)
 (btm_cb.mkey_cback)(bd_addr, status, key_flg );
 else
 (btm_cb.mkey_cback)(p_dev_rec->bd_addr, status, key_flg );
 }
}

void BpMemoryHeap::assertReallyMapped() const
{
 if (mHeapId == -1) {


 Parcel data, reply;
        data.writeInterfaceToken(IMemoryHeap::getInterfaceDescriptor());
 status_t err = remote()->transact(HEAP_ID, data, &reply);
 int parcel_fd = reply.readFileDescriptor();
 ssize_t size = reply.readInt32();
 uint32_t flags = reply.readInt32();
 uint32_t offset = reply.readInt32();

        ALOGE_IF(err, "binder=%p transaction failed fd=%d, size=%zd, err=%d (%s)",
                asBinder().get(), parcel_fd, size, err, strerror(-err));

 int fd = dup( parcel_fd );
        ALOGE_IF(fd==-1, "cannot dup fd=%d, size=%zd, err=%d (%s)",
                parcel_fd, size, err, strerror(errno));

 int access = PROT_READ;
 if (!(flags & READ_ONLY)) {
            access |= PROT_WRITE;
 }

 Mutex::Autolock _l(mLock);
 if (mHeapId == -1) {
            mRealHeap = true;
            mBase = mmap(0, size, access, MAP_SHARED, fd, offset);
 if (mBase == MAP_FAILED) {
                ALOGE("cannot map BpMemoryHeap (binder=%p), size=%zd, fd=%d (%s)",
                        asBinder().get(), size, fd, strerror(errno));
                close(fd);
 } else {
                mSize = size;
                mFlags = flags;
                mOffset = offset;
                android_atomic_write(fd, &mHeapId);
 }
 }
 }
}

static inline sp<IMemoryHeap> find_heap(const sp<IBinder>& binder) {
return gHeapCache->find_heap(binder);
}

uint32_t BpMemoryHeap::getOffset() const {
    assertMapped();
 return mOffset;
}

status_t BnMemory::onTransact(
 uint32_t code, const Parcel& data, Parcel* reply, uint32_t flags)
{
 switch(code) {
 case GET_MEMORY: {
            CHECK_INTERFACE(IMemory, data, reply);
 ssize_t offset;
 size_t size;
            reply->writeStrongBinder( getMemory(&offset, &size)->asBinder() );
            reply->writeInt32(offset);
            reply->writeInt32(size);
 return NO_ERROR;
 } break;
 default:
 return BBinder::onTransact(code, data, reply, flags);
 }
}

void* IMemory::pointer() const {
 ssize_t offset;
    sp<IMemoryHeap> heap = getMemory(&offset);
 void* const base = heap!=0 ? heap->base() : MAP_FAILED;
 if (base == MAP_FAILED)
 return 0;
 return static_cast<char*>(base) + offset;
}

