static void TryTransitionResultArrayToPacked(Handle<JSArray> array) {
if (!IsHoleyElementsKind(kind())) return;
int length = Smi::cast(array->length())->value();
Handle<FixedArrayBase> backing_store(array->elements());
if (!Subclass::IsPackedImpl(array, backing_store, 0, length)) {
return;
}
ElementsKind packed_kind = GetPackedElementsKind(kind());
Handle<Map> new_map =
JSObject::GetElementsTransitionMap(array, packed_kind);
JSObject::MigrateToMap(array, new_map);
if (FLAG_trace_elements_transitions) {
JSObject::PrintElementsTransition(stdout, array, kind(), backing_store,
                                       packed_kind, backing_store);
}
}

bt_status_t btif_av_execute_service(bool b_enable) {
 if (b_enable) {
/* TODO: Removed BTA_SEC_AUTHORIZE since the Java/App does not
 * handle this request in order to allow incoming connections to succeed.
 * We need to put this back once support for this is added */

/* Added BTA_AV_FEAT_NO_SCO_SSPD - this ensures that the BTA does not
 * auto-suspend av streaming on AG events(SCO or Call). The suspend shall
 * be initiated by the app/audioflinger layers */
/* Support for browsing for SDP record should work only if we enable BROWSE
 * while registering. */
#if (AVRC_METADATA_INCLUDED == TRUE)
    BTA_AvEnable(BTA_SEC_AUTHENTICATE,
                 BTA_AV_FEAT_RCTG | BTA_AV_FEAT_METADATA | BTA_AV_FEAT_VENDOR |
                     BTA_AV_FEAT_NO_SCO_SSPD
#if (AVRC_ADV_CTRL_INCLUDED == TRUE)
 | BTA_AV_FEAT_RCCT | BTA_AV_FEAT_ADV_CTRL |
                     BTA_AV_FEAT_BROWSE
#endif
 ,
                 bte_av_callback);
#else
    BTA_AvEnable(BTA_SEC_AUTHENTICATE,
 (BTA_AV_FEAT_RCTG | BTA_AV_FEAT_NO_SCO_SSPD), bte_av_callback);
#endif
    BTA_AvRegister(BTA_AV_CHNL_AUDIO, BTIF_AV_SERVICE_NAME, 0, NULL,
                   UUID_SERVCLASS_AUDIO_SOURCE);
 } else {
    BTA_AvDeregister(btif_av_cb.bta_handle);
    BTA_AvDisable();
 }
 return BT_STATUS_SUCCESS;
}

