void ACodec::ExecutingState::submitRegularOutputBuffers() {
 bool failed = false;
 for (size_t i = 0; i < mCodec->mBuffers[kPortIndexOutput].size(); ++i) {
 BufferInfo *info = &mCodec->mBuffers[kPortIndexOutput].editItemAt(i);

 if (mCodec->mNativeWindow != NULL) {
 if (info->mStatus != BufferInfo::OWNED_BY_US
 && info->mStatus != BufferInfo::OWNED_BY_NATIVE_WINDOW) {
                ALOGE("buffers should be owned by us or the surface");
                failed = true;
 break;
 }

 if (info->mStatus == BufferInfo::OWNED_BY_NATIVE_WINDOW) {
 continue;
 }
 } else {
 if (info->mStatus != BufferInfo::OWNED_BY_US) {
                ALOGE("buffers should be owned by us");
                failed = true;
 break;
 }
 }

        ALOGV("[%s] calling fillBuffer %u", mCodec->mComponentName.c_str(), info->mBufferID);

        info->checkWriteFence("submitRegularOutputBuffers");
 status_t err = mCodec->mOMX->fillBuffer(mCodec->mNode, info->mBufferID, info->mFenceFd);
        info->mFenceFd = -1;
 if (err != OK) {
            failed = true;
 break;
 }

        info->mStatus = BufferInfo::OWNED_BY_COMPONENT;
 }

 if (failed) {
        mCodec->signalError(OMX_ErrorUndefined, FAILED_TRANSACTION);
 }
}

long Cluster::CreateBlockGroup(long long start_offset, long long size,
 long long discard_padding) {
  assert(m_entries);
  assert(m_entries_size > 0);
  assert(m_entries_count >= 0);
  assert(m_entries_count < m_entries_size);

 IMkvReader* const pReader = m_pSegment->m_pReader;

 long long pos = start_offset;
 const long long stop = start_offset + size;


 long long prev = 1; // nonce
 long long next = 0; // nonce
 long long duration = -1; // really, this is unsigned

 long long bpos = -1;
 long long bsize = -1;

 while (pos < stop) {
 long len;
 const long long id = ReadID(pReader, pos, len);
 if (id < 0 || (pos + len) > stop)
 return E_FILE_FORMAT_INVALID;

    pos += len; // consume ID

 const long long size = ReadUInt(pReader, pos, len);
    assert(size >= 0); // TODO
    assert((pos + len) <= stop);

    pos += len; // consume size

 if (id == 0x21) { // Block ID
 if (bpos < 0) { // Block ID
        bpos = pos;
        bsize = size;
 }
 } else if (id == 0x1B) { // Duration ID
 if (size > 8)
 return E_FILE_FORMAT_INVALID;

      duration = UnserializeUInt(pReader, pos, size);

 if (duration < 0)
 return E_FILE_FORMAT_INVALID;
 } else if (id == 0x7B) { // ReferenceBlock
 if (size > 8 || size <= 0)
 return E_FILE_FORMAT_INVALID;
 const long size_ = static_cast<long>(size);

 long long time;

 long status = UnserializeInt(pReader, pos, size_, time);
      assert(status == 0);
 if (status != 0)
 return -1;

 if (time <= 0) // see note above
        prev = time;
 else // weird
        next = time;
 }

    pos += size; // consume payload
 if (pos > stop)
 return E_FILE_FORMAT_INVALID;
 }
 if (bpos < 0)
 return E_FILE_FORMAT_INVALID;

 if (pos != stop)
 return E_FILE_FORMAT_INVALID;
  assert(bsize >= 0);

 const long idx = m_entries_count;

 BlockEntry** const ppEntry = m_entries + idx;
 BlockEntry*& pEntry = *ppEntry;

  pEntry = new (std::nothrow)
 BlockGroup(this, idx, bpos, bsize, prev, next, duration, discard_padding);

 if (pEntry == NULL)
 return -1; // generic error

 BlockGroup* const p = static_cast<BlockGroup*>(pEntry);

 const long status = p->Parse();

 if (status == 0) { // success
 ++m_entries_count;
 return 0;
 }

 delete pEntry;
  pEntry = 0;

 return status;
}

bool Tags::Tag::ExpandSimpleTagsArray() {
