        DBG_RETURN(ret);
}

static int ehci_process_itd(EHCIState *ehci,
                            EHCIitd *itd,
                            uint32_t addr)
 {
     USBDevice *dev;
     USBEndpoint *ep;
    uint32_t i, len, pid, dir, devaddr, endp;
     uint32_t pg, off, ptr1, ptr2, max, mult;

     ehci->periodic_sched_active = PERIODIC_ACTIVE;

    dir =(itd->bufptr[1] & ITD_BUFPTR_DIRECTION);
    devaddr = get_field(itd->bufptr[0], ITD_BUFPTR_DEVADDR);
    endp = get_field(itd->bufptr[0], ITD_BUFPTR_EP);
    max = get_field(itd->bufptr[1], ITD_BUFPTR_MAXPKT);
    mult = get_field(itd->bufptr[2], ITD_BUFPTR_MULT);

    for(i = 0; i < 8; i++) {
        if (itd->transact[i] & ITD_XACT_ACTIVE) {
            pg   = get_field(itd->transact[i], ITD_XACT_PGSEL);
            off  = itd->transact[i] & ITD_XACT_OFFSET_MASK;
            ptr1 = (itd->bufptr[pg] & ITD_BUFPTR_MASK);
            ptr2 = (itd->bufptr[pg+1] & ITD_BUFPTR_MASK);
            len  = get_field(itd->transact[i], ITD_XACT_LENGTH);

            if (len > max * mult) {
                len = max * mult;
            }

            if (len > BUFF_SIZE) {
                return -1;
            }

            qemu_sglist_init(&ehci->isgl, ehci->device, 2, ehci->as);
            if (off + len > 4096) {
                /* transfer crosses page border */
                uint32_t len2 = off + len - 4096;
                uint32_t len1 = len - len2;
                qemu_sglist_add(&ehci->isgl, ptr1 + off, len1);
                qemu_sglist_add(&ehci->isgl, ptr2, len2);
            } else {
                qemu_sglist_add(&ehci->isgl, ptr1 + off, len);
            }

            pid = dir ? USB_TOKEN_IN : USB_TOKEN_OUT;

            dev = ehci_find_device(ehci, devaddr);
            ep = usb_ep_get(dev, pid, endp);
            if (ep && ep->type == USB_ENDPOINT_XFER_ISOC) {
                usb_packet_setup(&ehci->ipacket, pid, ep, 0, addr, false,
                                 (itd->transact[i] & ITD_XACT_IOC) != 0);
                usb_packet_map(&ehci->ipacket, &ehci->isgl);
                usb_handle_packet(dev, &ehci->ipacket);
                usb_packet_unmap(&ehci->ipacket, &ehci->isgl);
            } else {
                DPRINTF("ISOCH: attempt to addess non-iso endpoint\n");
                ehci->ipacket.status = USB_RET_NAK;
                ehci->ipacket.actual_length = 0;
            }
            qemu_sglist_destroy(&ehci->isgl);

            switch (ehci->ipacket.status) {
            case USB_RET_SUCCESS:
                break;
            default:
                fprintf(stderr, "Unexpected iso usb result: %d\n",
                        ehci->ipacket.status);
                /* Fall through */
            case USB_RET_IOERROR:
            case USB_RET_NODEV:
                /* 3.3.2: XACTERR is only allowed on IN transactions */
                if (dir) {
                    itd->transact[i] |= ITD_XACT_XACTERR;
                    ehci_raise_irq(ehci, USBSTS_ERRINT);
                }
                break;
            case USB_RET_BABBLE:
                itd->transact[i] |= ITD_XACT_BABBLE;
                ehci_raise_irq(ehci, USBSTS_ERRINT);
                break;
            case USB_RET_NAK:
                /* no data for us, so do a zero-length transfer */
                ehci->ipacket.actual_length = 0;
                break;
            }
            if (!dir) {
                set_field(&itd->transact[i], len - ehci->ipacket.actual_length,
                          ITD_XACT_LENGTH); /* OUT */
            } else {
                set_field(&itd->transact[i], ehci->ipacket.actual_length,
                          ITD_XACT_LENGTH); /* IN */
            }
            if (itd->transact[i] & ITD_XACT_IOC) {
                 ehci_raise_irq(ehci, USBSTS_INT);
             }
             itd->transact[i] &= ~ITD_XACT_ACTIVE;
         }
     }
    return 0;
 }

int ff_h263_decode_picture_header(MpegEncContext *s)
{
   int format, width, height, i;
    uint32_t startcode;

    align_get_bits(&s->gb);
   startcode= get_bits(&s->gb, 22-8);

   for(i= get_bits_left(&s->gb); i>24; i-=8) {
       startcode = ((startcode << 8) | get_bits(&s->gb, 8)) & 0x003FFFFF;

       if(startcode == 0x20)
           break;
   }

   if (startcode != 0x20) {
       av_log(s->avctx, AV_LOG_ERROR, "Bad picture start code\n");
       return -1;
   }
   /* temporal reference */
   i = get_bits(&s->gb, 8); /* picture timestamp */
   if( (s->picture_number&~0xFF)+i < s->picture_number)
       i+= 256;
   s->picture_number= (s->picture_number&~0xFF) + i;

   /* PTYPE starts here */
   if (get_bits1(&s->gb) != 1) {
       /* marker */
       av_log(s->avctx, AV_LOG_ERROR, "Bad marker\n");
       return -1;
   }
   if (get_bits1(&s->gb) != 0) {
       av_log(s->avctx, AV_LOG_ERROR, "Bad H263 id\n");
       return -1;      /* h263 id */
   }
   skip_bits1(&s->gb);         /* split screen off */
   skip_bits1(&s->gb);         /* camera  off */
   skip_bits1(&s->gb);         /* freeze picture release off */

   format = get_bits(&s->gb, 3);
   /*
       0    forbidden
       1    sub-QCIF
       10   QCIF
       7       extended PTYPE (PLUSPTYPE)
   */

   if (format != 7 && format != 6) {
       s->h263_plus = 0;
       /* H.263v1 */
        /* H.263v1 */
        width = ff_h263_format[format][0];
        height = ff_h263_format[format][1];
       if (!width)
           return -1;

        s->pict_type = AV_PICTURE_TYPE_I + get_bits1(&s->gb);


       s->h263_long_vectors = get_bits1(&s->gb);

       if (get_bits1(&s->gb) != 0) {
           av_log(s->avctx, AV_LOG_ERROR, "H263 SAC not supported\n");
           return -1; /* SAC: off */
       }
       s->obmc= get_bits1(&s->gb); /* Advanced prediction mode */
       s->unrestricted_mv = s->h263_long_vectors || s->obmc;

       s->pb_frame = get_bits1(&s->gb);
       s->chroma_qscale= s->qscale = get_bits(&s->gb, 5);
       skip_bits1(&s->gb); /* Continuous Presence Multipoint mode: off */

       s->width = width;
       s->height = height;
       s->avctx->sample_aspect_ratio= (AVRational){12,11};
       s->avctx->framerate = (AVRational){ 30000, 1001 };
   } else {
       int ufep;

       /* H.263v2 */
       s->h263_plus = 1;
       ufep = get_bits(&s->gb, 3); /* Update Full Extended PTYPE */

       /* ufep other than 0 and 1 are reserved */
       if (ufep == 1) {
           /* OPPTYPE */
           format = get_bits(&s->gb, 3);
           ff_dlog(s->avctx, "ufep=1, format: %d\n", format);
           s->custom_pcf= get_bits1(&s->gb);
           s->umvplus = get_bits1(&s->gb); /* Unrestricted Motion Vector */
           if (get_bits1(&s->gb) != 0) {
               av_log(s->avctx, AV_LOG_ERROR, "Syntax-based Arithmetic Coding (SAC) not supported\n");
           }
           s->obmc= get_bits1(&s->gb); /* Advanced prediction mode */
           s->h263_aic = get_bits1(&s->gb); /* Advanced Intra Coding (AIC) */
           s->loop_filter= get_bits1(&s->gb);
           s->unrestricted_mv = s->umvplus || s->obmc || s->loop_filter;

           s->h263_slice_structured= get_bits1(&s->gb);
           if (get_bits1(&s->gb) != 0) {
               av_log(s->avctx, AV_LOG_ERROR, "Reference Picture Selection not supported\n");
           }
           if (get_bits1(&s->gb) != 0) {
               av_log(s->avctx, AV_LOG_ERROR, "Independent Segment Decoding not supported\n");
           }
           s->alt_inter_vlc= get_bits1(&s->gb);
           s->modified_quant= get_bits1(&s->gb);
           if(s->modified_quant)
               s->chroma_qscale_table= ff_h263_chroma_qscale_table;

           skip_bits(&s->gb, 1); /* Prevent start code emulation */

           skip_bits(&s->gb, 3); /* Reserved */
       } else if (ufep != 0) {
           av_log(s->avctx, AV_LOG_ERROR, "Bad UFEP type (%d)\n", ufep);
           return -1;
       }

       /* MPPTYPE */
       s->pict_type = get_bits(&s->gb, 3);
       switch(s->pict_type){
       case 0: s->pict_type= AV_PICTURE_TYPE_I;break;
       case 1: s->pict_type= AV_PICTURE_TYPE_P;break;
       case 2: s->pict_type= AV_PICTURE_TYPE_P;s->pb_frame = 3;break;
       case 3: s->pict_type= AV_PICTURE_TYPE_B;break;
       case 7: s->pict_type= AV_PICTURE_TYPE_I;break; //ZYGO
       default:
           return -1;
       }
       skip_bits(&s->gb, 2);
       s->no_rounding = get_bits1(&s->gb);
       skip_bits(&s->gb, 4);

       /* Get the picture dimensions */
       if (ufep) {
           if (format == 6) {
               /* Custom Picture Format (CPFMT) */
               s->aspect_ratio_info = get_bits(&s->gb, 4);
               ff_dlog(s->avctx, "aspect: %d\n", s->aspect_ratio_info);
               /* aspect ratios:
               0 - forbidden
               1 - 1:1
               2 - 12:11 (CIF 4:3)
               3 - 10:11 (525-type 4:3)
               4 - 16:11 (CIF 16:9)
               5 - 40:33 (525-type 16:9)
               6-14 - reserved
               */
               width = (get_bits(&s->gb, 9) + 1) * 4;
               skip_bits1(&s->gb);
               height = get_bits(&s->gb, 9) * 4;
               ff_dlog(s->avctx, "\nH.263+ Custom picture: %dx%d\n",width,height);
               if (s->aspect_ratio_info == FF_ASPECT_EXTENDED) {
                   /* aspected dimensions */
                   s->avctx->sample_aspect_ratio.num= get_bits(&s->gb, 8);
                   s->avctx->sample_aspect_ratio.den= get_bits(&s->gb, 8);
               }else{
                   s->avctx->sample_aspect_ratio= ff_h263_pixel_aspect[s->aspect_ratio_info];
               }
           } else {
               width = ff_h263_format[format][0];
               height = ff_h263_format[format][1];
               s->avctx->sample_aspect_ratio= (AVRational){12,11};
           }
           if ((width == 0) || (height == 0))
               return -1;
           s->width = width;
           s->height = height;

           if(s->custom_pcf){
               int gcd;
               s->avctx->framerate.num  = 1800000;
               s->avctx->framerate.den  = 1000 + get_bits1(&s->gb);
               s->avctx->framerate.den *= get_bits(&s->gb, 7);
               if(s->avctx->framerate.den == 0){
                   av_log(s, AV_LOG_ERROR, "zero framerate\n");
                   return -1;
               }
               gcd= av_gcd(s->avctx->framerate.den, s->avctx->framerate.num);
               s->avctx->framerate.den /= gcd;
               s->avctx->framerate.num /= gcd;
           }else{
               s->avctx->framerate = (AVRational){ 30000, 1001 };
           }
       }

       if(s->custom_pcf){
           skip_bits(&s->gb, 2); //extended Temporal reference
       }

       if (ufep) {
           if (s->umvplus) {
               if(get_bits1(&s->gb)==0) /* Unlimited Unrestricted Motion Vectors Indicator (UUI) */
                   skip_bits1(&s->gb);
           }
           if(s->h263_slice_structured){
               if (get_bits1(&s->gb) != 0) {
                   av_log(s->avctx, AV_LOG_ERROR, "rectangular slices not supported\n");
               }
               if (get_bits1(&s->gb) != 0) {
                   av_log(s->avctx, AV_LOG_ERROR, "unordered slices not supported\n");
               }
           }
       }
        s->qscale = get_bits(&s->gb, 5);
    }

    s->mb_width = (s->width  + 15) / 16;
    s->mb_height = (s->height  + 15) / 16;
    s->mb_num = s->mb_width * s->mb_height;
       skip_bits(&s->gb, 3); /* Temporal reference for B-pictures */
       if (s->custom_pcf)
           skip_bits(&s->gb, 2); //extended Temporal reference
       skip_bits(&s->gb, 2); /* Quantization information for B-pictures */
   }

PHP_FUNCTION(imagepsencodefont)
{
	zval *fnt;
        char *enc, **enc_vector;
        int enc_len, *f_ind;

       if (zend_parse_parameters(ZEND_NUM_ARGS() TSRMLS_CC, "rs", &fnt, &enc, &enc_len) == FAILURE) {
                return;
        }
	ZEND_FETCH_RESOURCE(f_ind, int *, &fnt, -1, "Type 1 font", le_ps_font);

	if ((enc_vector = T1_LoadEncoding(enc)) == NULL) {
		php_error_docref(NULL TSRMLS_CC, E_WARNING, "Couldn't load encoding vector from %s", enc);
		RETURN_FALSE;
	}

	T1_DeleteAllSizes(*f_ind);
	if (T1_ReencodeFont(*f_ind, enc_vector)) {
		T1_DeleteEncoding(enc_vector);
		php_error_docref(NULL TSRMLS_CC, E_WARNING, "Couldn't re-encode font");
		RETURN_FALSE;
	}

	zend_list_insert(enc_vector, le_ps_enc TSRMLS_CC);

	RETURN_TRUE;
}

PHP_FUNCTION(stream_resolve_include_path)
{
        char *filename, *resolved_path;
        int filename_len;

       if (zend_parse_parameters(ZEND_NUM_ARGS() TSRMLS_CC, "s", &filename, &filename_len) == FAILURE) {
                return;
        }
	resolved_path = zend_resolve_path(filename, filename_len TSRMLS_CC);

	if (resolved_path) {
		RETURN_STRING(resolved_path, 0);
	}
	RETURN_FALSE;
}

static PHP_FUNCTION(gzopen)
{
	char *filename;
	char *mode;
	int filename_len, mode_len;
	int flags = REPORT_ERRORS;
        php_stream *stream;
        long use_include_path = 0;

       if (zend_parse_parameters(ZEND_NUM_ARGS() TSRMLS_CC, "ss|l", &filename, &filename_len, &mode, &mode_len, &use_include_path) == FAILURE) {
                return;
        }

	if (use_include_path) {
		flags |= USE_PATH;
	}

	stream = php_stream_gzopen(NULL, filename, mode, flags, NULL, NULL STREAMS_CC TSRMLS_CC);

	if (!stream) {
		RETURN_FALSE;
	}
	php_stream_to_zval(stream, return_value);
}

static int virtio_net_load(QEMUFile *f, void *opaque, int version_id)
{
    VirtIONet *n = opaque;
    VirtIODevice *vdev = VIRTIO_DEVICE(n);
    int ret, i, link_down;

    if (version_id < 2 || version_id > VIRTIO_NET_VM_VERSION)
        return -EINVAL;

    ret = virtio_load(vdev, f);
    if (ret) {
        return ret;
    }

    qemu_get_buffer(f, n->mac, ETH_ALEN);
    n->vqs[0].tx_waiting = qemu_get_be32(f);

    virtio_net_set_mrg_rx_bufs(n, qemu_get_be32(f));

    if (version_id >= 3)
        n->status = qemu_get_be16(f);

    if (version_id >= 4) {
        if (version_id < 8) {
            n->promisc = qemu_get_be32(f);
            n->allmulti = qemu_get_be32(f);
        } else {
            n->promisc = qemu_get_byte(f);
            n->allmulti = qemu_get_byte(f);
        }
    }

    if (version_id >= 5) {
        n->mac_table.in_use = qemu_get_be32(f);
        /* MAC_TABLE_ENTRIES may be different from the saved image */
        if (n->mac_table.in_use <= MAC_TABLE_ENTRIES) {
            qemu_get_buffer(f, n->mac_table.macs,
                            n->mac_table.in_use * ETH_ALEN);
        } else if (n->mac_table.in_use) {
            uint8_t *buf = g_malloc0(n->mac_table.in_use);
            qemu_get_buffer(f, buf, n->mac_table.in_use * ETH_ALEN);
            g_free(buf);
            n->mac_table.multi_overflow = n->mac_table.uni_overflow = 1;
            n->mac_table.in_use = 0;
        }
    }

    if (version_id >= 6)
        qemu_get_buffer(f, (uint8_t *)n->vlans, MAX_VLAN >> 3);

    if (version_id >= 7) {
        if (qemu_get_be32(f) && !peer_has_vnet_hdr(n)) {
            error_report("virtio-net: saved image requires vnet_hdr=on");
            return -1;
        }
    }

    if (version_id >= 9) {
        n->mac_table.multi_overflow = qemu_get_byte(f);
        n->mac_table.uni_overflow = qemu_get_byte(f);
    }

    if (version_id >= 10) {
        n->alluni = qemu_get_byte(f);
        n->nomulti = qemu_get_byte(f);
        n->nouni = qemu_get_byte(f);
        n->nobcast = qemu_get_byte(f);
    }

    if (version_id >= 11) {
        if (qemu_get_byte(f) && !peer_has_ufo(n)) {
            error_report("virtio-net: saved image requires TUN_F_UFO support");
            return -1;
        }
    }

    if (n->max_queues > 1) {
        if (n->max_queues != qemu_get_be16(f)) {
            error_report("virtio-net: different max_queues ");
            return -1;
         }

         n->curr_queues = qemu_get_be16(f);
         for (i = 1; i < n->curr_queues; i++) {
             n->vqs[i].tx_waiting = qemu_get_be32(f);
         }
        n->curr_guest_offloads = virtio_net_supported_guest_offloads(n);
    }

    if (peer_has_vnet_hdr(n)) {
        virtio_net_apply_guest_offloads(n);
    }

    virtio_net_set_queues(n);

    /* Find the first multicast entry in the saved MAC filter */
    for (i = 0; i < n->mac_table.in_use; i++) {
        if (n->mac_table.macs[i * ETH_ALEN] & 1) {
            break;
        }
    }
    n->mac_table.first_multi = i;

    /* nc.link_down can't be migrated, so infer link_down according
     * to link status bit in n->status */
    link_down = (n->status & VIRTIO_NET_S_LINK_UP) == 0;
    for (i = 0; i < n->max_queues; i++) {
        qemu_get_subqueue(n->nic, i)->link_down = link_down;
    }

    return 0;
}

