OMX_ERRORTYPE  omx_video::use_output_buffer(
        OMX_IN OMX_HANDLETYPE            hComp,
        OMX_INOUT OMX_BUFFERHEADERTYPE** bufferHdr,
        OMX_IN OMX_U32                   port,
        OMX_IN OMX_PTR                   appData,
        OMX_IN OMX_U32                   bytes,
        OMX_IN OMX_U8*                   buffer)
{
 (void)hComp, (void)port;
    OMX_ERRORTYPE eRet = OMX_ErrorNone;
    OMX_BUFFERHEADERTYPE       *bufHdr= NULL; // buffer header
 unsigned                         i= 0; // Temporary counter
 unsigned char *buf_addr = NULL;
#ifdef _MSM8974_
 int align_size;
#endif

    DEBUG_PRINT_HIGH("Inside use_output_buffer()");
 if (bytes != m_sOutPortDef.nBufferSize) {
        DEBUG_PRINT_ERROR("ERROR: use_output_buffer: Size Mismatch!! "
 "bytes[%u] != Port.nBufferSize[%u]", (unsigned int)bytes, (unsigned int)m_sOutPortDef.nBufferSize);
 return OMX_ErrorBadParameter;
 }

 if (!m_out_mem_ptr) {
        output_use_buffer = true;
 int nBufHdrSize        = 0;

        DEBUG_PRINT_LOW("Allocating First Output Buffer(%u)",(unsigned int)m_sOutPortDef.nBufferCountActual);
        nBufHdrSize        = m_sOutPortDef.nBufferCountActual * sizeof(OMX_BUFFERHEADERTYPE);
 /*
         * Memory for output side involves the following:
         * 1. Array of Buffer Headers
         * 2. Bitmask array to hold the buffer allocation details
         * In order to minimize the memory management entire allocation
         * is done in one step.
         */
        m_out_mem_ptr = (OMX_BUFFERHEADERTYPE  *)calloc(nBufHdrSize,1);
 if (m_out_mem_ptr == NULL) {
            DEBUG_PRINT_ERROR("ERROR: calloc() Failed for m_out_mem_ptr");
 return OMX_ErrorInsufficientResources;
 }

        m_pOutput_pmem = (struct pmem *) calloc(sizeof (struct pmem), m_sOutPortDef.nBufferCountActual);
 if (m_pOutput_pmem == NULL) {
            DEBUG_PRINT_ERROR("ERROR: calloc() Failed for m_pOutput_pmem");
 return OMX_ErrorInsufficientResources;
 }
#ifdef USE_ION
        m_pOutput_ion = (struct venc_ion *) calloc(sizeof (struct venc_ion), m_sOutPortDef.nBufferCountActual);
 if (m_pOutput_ion == NULL) {
            DEBUG_PRINT_ERROR("ERROR: calloc() Failed for m_pOutput_ion");
 return OMX_ErrorInsufficientResources;
 }
#endif
 if (m_out_mem_ptr) {
            bufHdr          =  m_out_mem_ptr;
            DEBUG_PRINT_LOW("Memory Allocation Succeeded for OUT port%p",m_out_mem_ptr);
 for (i=0; i < m_sOutPortDef.nBufferCountActual ; i++) {
                bufHdr->nSize              = sizeof(OMX_BUFFERHEADERTYPE);
                bufHdr->nVersion.nVersion  = OMX_SPEC_VERSION;
                bufHdr->nAllocLen          = bytes;
                bufHdr->nFilledLen         = 0;
                bufHdr->pAppPrivate        = appData;
                bufHdr->nOutputPortIndex   = PORT_INDEX_OUT;
                bufHdr->pBuffer            = NULL;
                bufHdr++;
                m_pOutput_pmem[i].fd = -1;
#ifdef USE_ION
                m_pOutput_ion[i].ion_device_fd =-1;
                m_pOutput_ion[i].fd_ion_data.fd=-1;
                m_pOutput_ion[i].ion_alloc_data.handle = 0;
#endif
 }
 } else {
            DEBUG_PRINT_ERROR("ERROR: Output buf mem alloc failed[0x%p]",m_out_mem_ptr);
            eRet =  OMX_ErrorInsufficientResources;
 }
 }

 for (i=0; i< m_sOutPortDef.nBufferCountActual; i++) {
 if (BITMASK_ABSENT(&m_out_bm_count,i)) {
 break;
 }
 }

 if (eRet == OMX_ErrorNone) {
 if (i < m_sOutPortDef.nBufferCountActual) {
 *bufferHdr = (m_out_mem_ptr + i );
 (*bufferHdr)->pBuffer = (OMX_U8 *)buffer;
 (*bufferHdr)->pAppPrivate = appData;

 if (!m_use_output_pmem) {
#ifdef USE_ION
#ifdef _MSM8974_
                align_size = (m_sOutPortDef.nBufferSize + (SZ_4K - 1)) & ~(SZ_4K - 1);
                m_pOutput_ion[i].ion_device_fd = alloc_map_ion_memory(align_size,
 &m_pOutput_ion[i].ion_alloc_data,
 &m_pOutput_ion[i].fd_ion_data,0);
#else
                m_pOutput_ion[i].ion_device_fd = alloc_map_ion_memory(
                        m_sOutPortDef.nBufferSize,
 &m_pOutput_ion[i].ion_alloc_data,
 &m_pOutput_ion[i].fd_ion_data,ION_FLAG_CACHED);
#endif
 if (m_pOutput_ion[i].ion_device_fd < 0) {
                    DEBUG_PRINT_ERROR("ERROR:ION device open() Failed");
 return OMX_ErrorInsufficientResources;
 }
                m_pOutput_pmem[i].fd = m_pOutput_ion[i].fd_ion_data.fd;
#else
                m_pOutput_pmem[i].fd = open (MEM_DEVICE,O_RDWR);

 if (m_pOutput_pmem[i].fd == 0) {
                    m_pOutput_pmem[i].fd = open (MEM_DEVICE,O_RDWR);
 }

 if (m_pOutput_pmem[i].fd < 0) {
                    DEBUG_PRINT_ERROR("ERROR: /dev/pmem_adsp open() Failed");
 return OMX_ErrorInsufficientResources;
 }
#endif

                 m_pOutput_pmem[i].size = m_sOutPortDef.nBufferSize;
                 m_pOutput_pmem[i].offset = 0;

                m_pOutput_pmem[i].buffer = (OMX_U8 *)SECURE_BUFPTR;
                 if(!secure_session) {
 #ifdef _MSM8974_
                     m_pOutput_pmem[i].buffer = (unsigned char *)mmap(NULL,
                        align_size,PROT_READ|PROT_WRITE,
                        MAP_SHARED,m_pOutput_pmem[i].fd,0);
#else
                    m_pOutput_pmem[i].buffer = (unsigned char *)mmap(NULL,
                        m_pOutput_pmem[i].size,PROT_READ|PROT_WRITE,
                        MAP_SHARED,m_pOutput_pmem[i].fd,0);

 #endif
                 if (m_pOutput_pmem[i].buffer == MAP_FAILED) {
                         DEBUG_PRINT_ERROR("ERROR: mmap() Failed");
                     close(m_pOutput_pmem[i].fd);
 #ifdef USE_ION
                     free_ion_memory(&m_pOutput_ion[i]);
#endif
 return OMX_ErrorInsufficientResources;
 }
 }
 } else {
                OMX_QCOM_PLATFORM_PRIVATE_PMEM_INFO *pParam = reinterpret_cast<OMX_QCOM_PLATFORM_PRIVATE_PMEM_INFO*>((*bufferHdr)->pAppPrivate);
                DEBUG_PRINT_LOW("Inside qcom_ext pParam: %p", pParam);

 if (pParam) {
                    DEBUG_PRINT_LOW("Inside qcom_ext with luma:(fd:%lu,offset:0x%x)", pParam->pmem_fd, (int)pParam->offset);
                    m_pOutput_pmem[i].fd = pParam->pmem_fd;
                    m_pOutput_pmem[i].offset = pParam->offset;
                    m_pOutput_pmem[i].size = m_sOutPortDef.nBufferSize;
                    m_pOutput_pmem[i].buffer = (unsigned char *)buffer;
 } else {
                    DEBUG_PRINT_ERROR("ERROR: Invalid AppData given for PMEM o/p UseBuffer case");
 return OMX_ErrorBadParameter;
 }
                buf_addr = (unsigned char *)buffer;
 }

            DEBUG_PRINT_LOW("use_out:: bufhdr = %p, pBuffer = %p, m_pOutput_pmem[i].buffer = %p",
 (*bufferHdr), (*bufferHdr)->pBuffer, m_pOutput_pmem[i].buffer);
 if (dev_use_buf(&m_pOutput_pmem[i],PORT_INDEX_OUT,i) != true) {
                DEBUG_PRINT_ERROR("ERROR: dev_use_buf Failed for o/p buf");
 return OMX_ErrorInsufficientResources;
 }

            BITMASK_SET(&m_out_bm_count,i);
 } else {
            DEBUG_PRINT_ERROR("ERROR: All o/p Buffers have been Used, invalid use_buf call for "
 "index = %u", i);
            eRet = OMX_ErrorInsufficientResources;
 }
 }
 return eRet;
}

status_t StreamingProcessor::processRecordingFrame() {
    ATRACE_CALL();
 status_t res;
    sp<Camera2Heap> recordingHeap;
 size_t heapIdx = 0;
 nsecs_t timestamp;

    sp<Camera2Client> client = mClient.promote();
 if (client == 0) {
 BufferItem imgBuffer;
        res = mRecordingConsumer->acquireBuffer(&imgBuffer, 0);
 if (res != OK) {
 if (res != BufferItemConsumer::NO_BUFFER_AVAILABLE) {
                ALOGE("%s: Camera %d: Can't acquire recording buffer: %s (%d)",
                        __FUNCTION__, mId, strerror(-res), res);
 }
 return res;
 }
        mRecordingConsumer->releaseBuffer(imgBuffer);
 return OK;
 }

 {
 /* acquire SharedParameters before mMutex so we don't dead lock
            with Camera2Client code calling into StreamingProcessor */
 SharedParameters::Lock l(client->getParameters());
 Mutex::Autolock m(mMutex);
 BufferItem imgBuffer;
        res = mRecordingConsumer->acquireBuffer(&imgBuffer, 0);
 if (res != OK) {
 if (res != BufferItemConsumer::NO_BUFFER_AVAILABLE) {
                ALOGE("%s: Camera %d: Can't acquire recording buffer: %s (%d)",
                        __FUNCTION__, mId, strerror(-res), res);
 }
 return res;
 }
        timestamp = imgBuffer.mTimestamp;

        mRecordingFrameCount++;
        ALOGVV("OnRecordingFrame: Frame %d", mRecordingFrameCount);

 if (l.mParameters.state != Parameters::RECORD &&
                l.mParameters.state != Parameters::VIDEO_SNAPSHOT) {
            ALOGV("%s: Camera %d: Discarding recording image buffers "
 "received after recording done", __FUNCTION__,
                    mId);
            mRecordingConsumer->releaseBuffer(imgBuffer);
 return INVALID_OPERATION;
 }

 if (mRecordingHeap == 0) {
 size_t payloadSize = sizeof(VideoNativeMetadata);
            ALOGV("%s: Camera %d: Creating recording heap with %zu buffers of "
 "size %zu bytes", __FUNCTION__, mId,
                    mRecordingHeapCount, payloadSize);

            mRecordingHeap = new Camera2Heap(payloadSize, mRecordingHeapCount,
 "Camera2Client::RecordingHeap");
 if (mRecordingHeap->mHeap->getSize() == 0) {
                ALOGE("%s: Camera %d: Unable to allocate memory for recording",
                        __FUNCTION__, mId);
                mRecordingConsumer->releaseBuffer(imgBuffer);
 return NO_MEMORY;
 }
 for (size_t i = 0; i < mRecordingBuffers.size(); i++) {
 if (mRecordingBuffers[i].mBuf !=
 BufferItemConsumer::INVALID_BUFFER_SLOT) {
                    ALOGE("%s: Camera %d: Non-empty recording buffers list!",
                            __FUNCTION__, mId);
 }
 }
            mRecordingBuffers.clear();
            mRecordingBuffers.setCapacity(mRecordingHeapCount);
            mRecordingBuffers.insertAt(0, mRecordingHeapCount);

            mRecordingHeapHead = 0;
            mRecordingHeapFree = mRecordingHeapCount;
 }

 if (mRecordingHeapFree == 0) {
            ALOGE("%s: Camera %d: No free recording buffers, dropping frame",
                    __FUNCTION__, mId);
            mRecordingConsumer->releaseBuffer(imgBuffer);
 return NO_MEMORY;
 }

        heapIdx = mRecordingHeapHead;
        mRecordingHeapHead = (mRecordingHeapHead + 1) % mRecordingHeapCount;
        mRecordingHeapFree--;

        ALOGVV("%s: Camera %d: Timestamp %lld",
                __FUNCTION__, mId, timestamp);

 ssize_t offset;
 size_t size;
        sp<IMemoryHeap> heap =
                mRecordingHeap->mBuffers[heapIdx]->getMemory(&offset,
 &size);

 VideoNativeMetadata *payload = reinterpret_cast<VideoNativeMetadata*>(

             (uint8_t*)heap->getBase() + offset);
         payload->eType = kMetadataBufferTypeANWBuffer;
         payload->pBuffer = imgBuffer.mGraphicBuffer->getNativeBuffer();
         payload->nFenceFd = -1;

         ALOGVV("%s: Camera %d: Sending out ANWBuffer %p",
                __FUNCTION__, mId, payload->pBuffer);

        mRecordingBuffers.replaceAt(imgBuffer, heapIdx);
        recordingHeap = mRecordingHeap;
 }

 Camera2Client::SharedCameraCallbacks::Lock l(client->mSharedCameraCallbacks);
 if (l.mRemoteCallback != 0) {
        l.mRemoteCallback->dataCallbackTimestamp(timestamp,
                CAMERA_MSG_VIDEO_FRAME,
                recordingHeap->mBuffers[heapIdx]);
 } else {
        ALOGW("%s: Camera %d: Remote callback gone", __FUNCTION__, mId);
 }

 return OK;
}

status_t OMXNodeInstance::useGraphicBuffer2_l(
        OMX_U32 portIndex, const sp<GraphicBuffer>& graphicBuffer,
        OMX::buffer_id *buffer) {

    OMX_PARAM_PORTDEFINITIONTYPE def;
 InitOMXParams(&def);
    def.nPortIndex = portIndex;
    OMX_ERRORTYPE err = OMX_GetParameter(mHandle, OMX_IndexParamPortDefinition, &def);
 if (err != OMX_ErrorNone) {
        OMX_INDEXTYPE index = OMX_IndexParamPortDefinition;
        CLOG_ERROR(getParameter, err, "%s(%#x): %s:%u",
                asString(index), index, portString(portIndex), portIndex);

         return UNKNOWN_ERROR;
     }

    BufferMeta *bufferMeta = new BufferMeta(graphicBuffer);

     OMX_BUFFERHEADERTYPE *header = NULL;
     OMX_U8* bufferHandle = const_cast<OMX_U8*>(
 reinterpret_cast<const OMX_U8*>(graphicBuffer->handle));

    err = OMX_UseBuffer(
            mHandle,
 &header,
            portIndex,
            bufferMeta,
            def.nBufferSize,
            bufferHandle);

 if (err != OMX_ErrorNone) {
        CLOG_ERROR(useBuffer, err, BUFFER_FMT(portIndex, "%u@%p", def.nBufferSize, bufferHandle));
 delete bufferMeta;
        bufferMeta = NULL;
 *buffer = 0;
 return StatusFromOMXError(err);
 }

    CHECK_EQ(header->pBuffer, bufferHandle);
    CHECK_EQ(header->pAppPrivate, bufferMeta);

 *buffer = makeBufferID(header);

    addActiveBuffer(portIndex, *buffer);
    CLOG_BUFFER(useGraphicBuffer2, NEW_BUFFER_FMT(
 *buffer, portIndex, "%u@%p", def.nBufferSize, bufferHandle));
 return OK;
}

int main(int argc, char **argv) {
 const char *test_name = NULL;
 bool skip_sanity_suite = false;

 for (int i = 1; i < argc; ++i) {
 if (!strcmp("--help", argv[i])) {
      print_usage(argv[0]);
 return 0;
 }

 if (!strcmp("--insanity", argv[i])) {
      skip_sanity_suite = true;
 continue;
 }

 if (!is_valid(argv[i])) {
      printf("Error: invalid test name.\n");
      print_usage(argv[0]);
 return -1;
 }

 if (test_name != NULL) {
      printf("Error: invalid arguments.\n");
      print_usage(argv[0]);
 return -1;
 }

    test_name = argv[i];
 }

 if (is_shell_running()) {
    printf("Run 'adb shell stop' before running %s.\n", argv[0]);
 return -1;
 }

 config_t *config = config_new(CONFIG_FILE_PATH);
 if (!config) {
    printf("Error: unable to open stack config file.\n");
    print_usage(argv[0]);
 return -1;
 }

 for (const config_section_node_t *node = config_section_begin(config); node != config_section_end(config); node = config_section_next(node)) {
 const char *name = config_section_name(node);
 if (config_has_key(config, name, "LinkKey") && string_to_bdaddr(name, &bt_remote_bdaddr)) {
 break;
 }
 }

  config_free(config);

 if (bdaddr_is_empty(&bt_remote_bdaddr)) {
    printf("Error: unable to find paired device in config file.\n");
    print_usage(argv[0]);
 return -1;
 }

 if (!hal_open(callbacks_get_adapter_struct())) {
    printf("Unable to open Bluetooth HAL.\n");
 return 1;
 }

 if (!btsocket_init()) {
    printf("Unable to initialize Bluetooth sockets.\n");
 return 2;
 }

 if (!pan_init()) {
    printf("Unable to initialize PAN.\n");
 return 3;
 }

 if (!gatt_init()) {
    printf("Unable to initialize GATT.\n");
 return 4;
 }

  watchdog_running = true;
  pthread_create(&watchdog_thread, NULL, watchdog_fn, NULL);

 static const char *DEFAULT  = "\x1b[0m";
 static const char *GREEN = "\x1b[0;32m";
 static const char *RED   = "\x1b[0;31m";

 if (!isatty(fileno(stdout))) {
    DEFAULT = GREEN = RED = "";
 }

 int pass = 0;
 int fail = 0;
 int case_num = 0;

 if (!skip_sanity_suite) {
 for (size_t i = 0; i < sanity_suite_size; ++i) {
 if (!test_name || !strcmp(test_name, sanity_suite[i].function_name)) {
        callbacks_init();
 if (sanity_suite[i].function()) {
          printf("[%4d] %-64s [%sPASS%s]\n", ++case_num, sanity_suite[i].function_name, GREEN, DEFAULT);
 ++pass;
 } else {
          printf("[%4d] %-64s [%sFAIL%s]\n", ++case_num, sanity_suite[i].function_name, RED, DEFAULT);
 ++fail;
 }
        callbacks_cleanup();
 ++watchdog_id;
 }
 }
 }

 if (fail) {
    printf("\n%sSanity suite failed with %d errors.%s\n", RED, fail, DEFAULT);
    hal_close();
 return 4;
 }


   for (size_t i = 0; i < test_suite_size; ++i) {
     if (!test_name || !strcmp(test_name, test_suite[i].function_name)) {
       callbacks_init();
      CALL_AND_WAIT(bt_interface->enable(), adapter_state_changed);
       if (test_suite[i].function()) {
         printf("[%4d] %-64s [%sPASS%s]\n", ++case_num, test_suite[i].function_name, GREEN, DEFAULT);
         ++pass;
 } else {
        printf("[%4d] %-64s [%sFAIL%s]\n", ++case_num, test_suite[i].function_name, RED, DEFAULT);
 ++fail;
 }
      CALL_AND_WAIT(bt_interface->disable(), adapter_state_changed);
      callbacks_cleanup();
 ++watchdog_id;
 }
 }

  printf("\n");

 if (fail) {
    printf("%d/%d tests failed. See above for failed test cases.\n", fail, sanity_suite_size + test_suite_size);
 } else {
    printf("All tests passed!\n");
 }

  watchdog_running = false;
  pthread_join(watchdog_thread, NULL);

  hal_close();

 return 0;
}

png_have_neon(png_structp png_ptr)
{
 FILE *f = fopen("/proc/cpuinfo", "rb");

 if (f != NULL)
 {
 /* This is a simple state machine which reads the input byte-by-byte until
       * it gets a match on the 'neon' feature or reaches the end of the stream.
       */
 static const char ch_feature[] = { 70, 69, 65, 84, 85, 82, 69, 83 };
 static const char ch_neon[] = { 78, 69, 79, 78 };

 enum
 {
 StartLine, Feature, Colon, StartTag, Neon, HaveNeon, SkipTag, SkipLine
 }  state;
 int counter;

 for (state=StartLine, counter=0;;)
 {
 int ch = fgetc(f);

 if (ch == EOF)
 {
 /* EOF means error or end-of-file, return false; neon at EOF is
             * assumed to be a mistake.
             */
            fclose(f);
 return 0;
 }

 switch (state)
 {
 case StartLine:
 /* Match spaces at the start of line */
 if (ch <= 32) /* skip control characters and space */
 break;

               counter=0;
               state = Feature;
 /* FALL THROUGH */

 case Feature:
 /* Match 'FEATURE', ASCII case insensitive. */
 if ((ch & ~0x20) == ch_feature[counter])
 {
 if (++counter == (sizeof ch_feature))

                      state = Colon;
                   break;
                }
                /* did not match 'feature' */
                state = SkipLine;
                /* FALL THROUGH */

 case SkipLine:
            skipLine:
 /* Skip everything until we see linefeed or carriage return */
 if (ch != 10 && ch != 13)
 break;

               state = StartLine;
 break;

 case Colon:
 /* Match any number of space or tab followed by ':' */
 if (ch == 32 || ch == 9)
 break;

 if (ch == 58) /* i.e. ':' */
 {
                  state = StartTag;
 break;
 }

 /* Either a bad line format or a 'feature' prefix followed by
                * other characters.
                */
               state = SkipLine;
 goto skipLine;

 case StartTag:
 /* Skip space characters before a tag */
 if (ch == 32 || ch == 9)
 break;

               state = Neon;
               counter = 0;
 /* FALL THROUGH */

 case Neon:
 /* Look for 'neon' tag */
 if ((ch & ~0x20) == ch_neon[counter])
 {
 if (++counter == (sizeof ch_neon))
                     state = HaveNeon;
 break;
 }

               state = SkipTag;
 /* FALL THROUGH */

 case SkipTag:
 /* Skip non-space characters */
 if (ch == 10 || ch == 13)
                  state = StartLine;

 else if (ch == 32 || ch == 9)
                  state = StartTag;
 break;

 case HaveNeon:
 /* Have seen a 'neon' prefix, but there must be a space or new
                * line character to terminate it.
                */
 if (ch == 10 || ch == 13 || ch == 32 || ch == 9)
 {
                  fclose(f);
 return 1;
 }

               state = SkipTag;
 break;

 default:
               png_error(png_ptr, "png_have_neon: internal error (bug)");
 }

       }
    }

    else
       png_warning(png_ptr, "/proc/cpuinfo open failed");

    return 0;
 }

int readpng_init(FILE *infile, ulg *pWidth, ulg *pHeight)
{
    uch sig[8];


 /* first do a quick check that the file really is a PNG image; could
     * have used slightly more general png_sig_cmp() function instead */

    fread(sig, 1, 8, infile);
 if (png_sig_cmp(sig, 0, 8))
 return 1; /* bad signature */



     /* could pass pointers to user-defined error handlers instead of NULLs: */

    png_ptr = png_create_read_struct(PNG_LIBPNG_VER_STRING, NULL, NULL, NULL);
     if (!png_ptr)
         return 4;   /* out of memory */

    info_ptr = png_create_info_struct(png_ptr);
 if (!info_ptr) {
        png_destroy_read_struct(&png_ptr, NULL, NULL);
 return 4; /* out of memory */
 }


 /* we could create a second info struct here (end_info), but it's only
     * useful if we want to keep pre- and post-IDAT chunk info separated
     * (mainly for PNG-aware image editors and converters) */


 /* setjmp() must be called in every function that calls a PNG-reading
     * libpng function */

 if (setjmp(png_jmpbuf(png_ptr))) {
        png_destroy_read_struct(&png_ptr, &info_ptr, NULL);
 return 2;
 }


    png_init_io(png_ptr, infile);
    png_set_sig_bytes(png_ptr, 8); /* we already read the 8 signature bytes */

    png_read_info(png_ptr, info_ptr); /* read all PNG info up to image data */


 /* alternatively, could make separate calls to png_get_image_width(),
     * etc., but want bit_depth and color_type for later [don't care about
     * compression_type and filter_type => NULLs] */

    png_get_IHDR(png_ptr, info_ptr, &width, &height, &bit_depth, &color_type,
      NULL, NULL, NULL);
 *pWidth = width;
 *pHeight = height;


 /* OK, that's all we need for now; return happy */

 return 0;
}

set_value(png_bytep row, size_t rowbytes, png_uint_32 x, unsigned int bit_depth,
   png_uint_32 value, png_const_bytep gamma_table, double conv)
{
 unsigned int mask = (1U << bit_depth)-1;

   x *= bit_depth; /* Maximum x is 4*1024, maximum bit_depth is 16 */

 if (value <= mask)
 {
      png_uint_32 offset = x >> 3;

 if (offset < rowbytes && (bit_depth < 16 || offset+1 < rowbytes))
 {
         row += offset;

 switch (bit_depth)
 {
 case 1:
 case 2:
 case 4:
 /* Don't gamma correct - values get smashed */
 {
 unsigned int shift = (8 - bit_depth) - (x & 0x7U);

                  mask <<= shift;
                  value = (value << shift) & mask;
 *row = (png_byte)((*row & ~mask) | value);
 }
 return;

 default:
               fprintf(stderr, "makepng: bad bit depth (internal error)\n");

                exit(1);

             case 16:
               value = (unsigned int)floor(65535*pow(value/65535.,conv)+.5);
                *row++ = (png_byte)(value >> 8);
                *row = (png_byte)value;
                return;

 case 8:
 *row = gamma_table[value];
 return;
 }
 }

 else
 {
         fprintf(stderr, "makepng: row buffer overflow (internal error)\n");
         exit(1);
 }
 }

 else
 {
      fprintf(stderr, "makepng: component overflow (internal error)\n");
      exit(1);

    }
 }

transform_name(int t)
 /* The name, if 't' has multiple bits set the name of the lowest set bit is
    * returned.
    */
{
 unsigned int i;


    t &= -t; /* first set bit */

   for (i=0; i<TTABLE_SIZE; ++i)
    {
       if ((transform_info[i].transform & t) != 0)
          return transform_info[i].name;
 }

 return "invalid transform";
}

