bool mkvparser::Match(IMkvReader* pReader, long long& pos, unsigned long id_,
                      unsigned char*& buf, size_t& buflen) {
  assert(pReader);
  assert(pos >= 0);
  long long total, available;
  long status = pReader->Length(&total, &available);
  assert(status >= 0);
  assert((total < 0) || (available <= total));
  if (status < 0)
     return false;

  long len;
  const long long id = ReadUInt(pReader, pos, len);
  assert(id >= 0);
  assert(len > 0);
  assert(len <= 8);
  assert((pos + len) <= available);

  if ((unsigned long)id != id_)
     return false;

   pos += len;  // consume id

  const long long size_ = ReadUInt(pReader, pos, len);
  assert(size_ >= 0);
  assert(len > 0);
  assert(len <= 8);
  assert((pos + len) <= available);

   pos += len;  // consume length of size of payload
  assert((pos + size_) <= available);

  const long buflen_ = static_cast<long>(size_);

  buf = new (std::nothrow) unsigned char[buflen_];
  assert(buf);  // TODO

   status = pReader->Read(pos, buflen_, buf);
  assert(status == 0);  // TODO

   buflen = buflen_;

  pos += size_;  // consume size of payload
   return true;
 }

long VideoTrack::Parse(Segment* pSegment, const Info& info,
 long long element_start, long long element_size,
 VideoTrack*& pResult) {
 if (pResult)
 return -1;

 if (info.type != Track::kVideo)
 return -1;


   long long width = 0;
   long long height = 0;
   double rate = 0.0;

   IMkvReader* const pReader = pSegment->m_pReader;

 const Settings& s = info.settings;
  assert(s.start >= 0);
  assert(s.size >= 0);

 long long pos = s.start;
  assert(pos >= 0);

 const long long stop = pos + s.size;

 while (pos < stop) {
 long long id, size;

 const long status = ParseElementHeader(pReader, pos, stop, id, size);

 if (status < 0) // error
 return status;

 if (id == 0x30) { // pixel width
      width = UnserializeUInt(pReader, pos, size);

 if (width <= 0)
 return E_FILE_FORMAT_INVALID;
 } else if (id == 0x3A) { // pixel height
      height = UnserializeUInt(pReader, pos, size);


       if (height <= 0)
         return E_FILE_FORMAT_INVALID;
     } else if (id == 0x0383E3) {  // frame rate
       const long status = UnserializeFloat(pReader, pos, size, rate);

 if (status < 0)
 return status;

 if (rate <= 0)
 return E_FILE_FORMAT_INVALID;

     }

     pos += size;  // consume payload
    assert(pos <= stop);
   }

  assert(pos == stop);

   VideoTrack* const pTrack =
       new (std::nothrow) VideoTrack(pSegment, element_start, element_size);

 if (pTrack == NULL)
 return -1; // generic error

 const int status = info.Copy(pTrack->m_info);

 if (status) { // error
 delete pTrack;
 return status;
 }


   pTrack->m_width = width;
   pTrack->m_height = height;
   pTrack->m_rate = rate;

   pResult = pTrack;
 return 0; // success
}

u32 h264bsdInit(storage_t *pStorage, u32 noOutputReordering)
{

/* Variables */
    u32 size;
/* Code */

    ASSERT(pStorage);

    h264bsdInitStorage(pStorage);

 /* allocate mbLayer to be next multiple of 64 to enable use of

      * specific NEON optimized "memset" for clearing the structure */
     size = (sizeof(macroblockLayer_t) + 63) & ~0x3F;

    pStorage->mbLayer = (macroblockLayer_t*)H264SwDecMalloc(size);
     if (!pStorage->mbLayer)
         return HANTRO_NOK;

 if (noOutputReordering)
        pStorage->noReordering = HANTRO_TRUE;

 return HANTRO_OK;
}

 std::string Backtrace::GetFunctionName(uintptr_t pc, uintptr_t* offset) {
   std::string func_name = GetFunctionNameRaw(pc, offset);
  if (!func_name.empty()) {
#if defined(__APPLE__)
    if (func_name[0] != '_') {
      return func_name;
    }
#endif
    char* name = __cxa_demangle(func_name.c_str(), 0, 0, 0);
    if (name) {
      func_name = name;
      free(name);
    }
  }
   return func_name;
 }

